    <div class="card hi-card"><h3>High-risk entities <span class="badge">${RED().length} high</span></h3>${RED().sort((a,b)=>(a.category==='competitor'?0:1)-(b.category==='competitor'?0:1)).map(e=>`<div class="wrow" data-ent="${e.id}">${logo(e.id,e.name,1)}<div><b>${esc(e.name.split('(')[0])} <span class="note" style="font-weight:400">· ${esc(e.category)}</span></b><p>${esc(e.risk.reason)}</p></div></div>`).join('')}
      <p class="note"><a href="#competitors">Competitor board →</a> · <a href="#portfolio">Portfolio risk →</a></p></div>
