function vValBaseline(){
  const ff=D.ff, px=D.market.snapshot.GOTO.price, W=760, rowH=30, top=26, left=270, sc=v=>left+(v/120)*(W-left-30);
  const svg=`<svg viewBox="0 0 ${W} ${top+ff.length*rowH+30}" width="100%" role="img" aria-label="Football field">
   ${[0,20,40,60,80,100,120].map(t=>`<line x1="${sc(t)}" x2="${sc(t)}" y1="${top-8}" y2="${top+ff.length*rowH}" stroke="${css('--line')}"/><text x="${sc(t)}" y="${top+ff.length*rowH+16}" text-anchor="middle">Rp${t}</text>`).join('')}
   ${ff.map((r,i)=>{const y=top+i*rowH; const c=r.m.startsWith('DCF')?'#6250d6':(r.m.startsWith('Comps')||r.m.startsWith('SOTP'))?'#1baf7a':'#0b5cad';
     return `<text x="${left-10}" y="${y+18}" text-anchor="end">${esc(r.m.replace(' - ',' · ').slice(0,46))}</text><rect x="${sc(r.lo)}" y="${y+7}" width="${Math.max(2,sc(r.hi)-sc(r.lo))}" height="16" rx="3" fill="${c}" opacity=".85"/><rect x="${sc(r.base)-1.5}" y="${y+4}" width="3" height="22" fill="${css('--ink')}"/><text x="${sc(r.hi)+5}" y="${y+19}">${fmt(r.lo)}–${fmt(r.hi)}</text>`;}).join('')}
   <line x1="${sc(px)}" x2="${sc(px)}" y1="${top-12}" y2="${top+ff.length*rowH}" stroke="#e06c1b" stroke-width="2" stroke-dasharray="4 3"/><text x="${sc(px)+4}" y="${top-14}" style="fill:#e06c1b">Price Rp${px}</text></svg>`;
  const C=D.cap; const capRows=[['GoRide 7.5% of ODS gross revenue','s075'],['GoRide 10% (base, BRIDS)','s100'],['GoRide 12.5%','s125'],['GoRide 15% (UOB-implied)','s150'],['No cap (counterfactual)','nocap']];
  const dc=D.dcf;
  $('#v-valuation').innerHTML=`
   <div class="card ff"><h3>Football field <small>Rp per share · bar = range, black tick = base</small></h3><div class="tw">${svg}</div></div>
   <div class="grid g3" style="margin-top:14px">
    <div class="card"><h3>DCF essentials</h3><table><tbody>
     <tr><td>Value per share</td><td class="r mono"><b>Rp${fmt(dc['DCF value per share (IDR)'],1)}</b></td></tr>
     <tr><td>WACC</td><td class="r mono">${fmt(dc.WACC*100,2)}%</td></tr>
     <tr><td>Cost of equity (incl. 1% policy premium)</td><td class="r mono">${fmt(dc['Cost of equity']*100,2)}%</td></tr>
     <tr><td>Unlevered beta (segment-weighted)</td><td class="r mono">${fmt(dc['Unlevered beta (segment-weighted peers; see Comps)'],2)}</td></tr>
     <tr><td>Relevered beta</td><td class="r mono">${fmt(dc['Relevered beta = Bu x (1 + (1 - t) x D/E)'],2)}</td></tr>
     <tr><td>Terminal growth</td><td class="r mono">${fmt(dc['Terminal growth (nominal IDR)']*100,1)}%</td></tr>
     <tr><td>Enterprise value (Rp bn)</td><td class="r mono">${fmt(dc['Enterprise value'])}</td></tr>
     <tr><td>Equity value (Rp bn)</td><td class="r mono">${fmt(dc['Equity value'])}</td></tr>
     <tr><td>Terminal value % of EV</td><td class="r mono">${fmt(dc['Terminal value as % of EV']*100,0)}%</td></tr></tbody></table></div>
    <div class="card"><h3>8% GoRide cap sensitivity</h3><table><thead><tr><th>Scenario</th><th class="r">Value</th><th class="r">FY27 EBITDA</th></tr></thead><tbody>${capRows.map(([l,k])=>`<tr><td>${l}</td><td class="r mono">Rp${fmt(C[k].vps,1)}</td><td class="r mono">${fmt(C[k].e27)}</td></tr>`).join('')}</tbody></table>
     <p class="note">Cap applies to 2-wheel ride-hailing only (Perpres 27/2026). Commission 20%→8% = 60% of GoRide gross revenue lost; 20% opex offset; promotion savings 0.1-0.2% of GTV.</p></div>
    <div class="card"><h3>Projection path <small>Rp bn</small></h3><div style="height:220px"><canvas id="c-proj"></canvas></div></div>
   </div>
   <div class="card" style="margin-top:14px"><h3>Broker target prices <small>${D.brokers.length} brokers</small></h3><div class="tw"><table><thead><tr><th>Broker</th><th class="r">TP</th><th>Rating</th><th>Date</th><th class="r">vs Rp${px}</th><th>Post-fall?</th><th>Source</th></tr></thead><tbody>${D.brokers.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(b=>`<tr><td>${esc(b.b)}</td><td class="r mono">Rp${b.tp}</td><td>${esc(b.rating)}</td><td class="mono">${esc(b.date)}</td><td class="r mono up">+${fmt((b.tp/px-1)*100,0)}%</td><td>${b.recent?'<span class="sev low">yes</span>':''}</td><td>${b.url&&b.url.startsWith('http')?link(b.url,'link'):esc((b.url||'').slice(0,40))}</td></tr>`).join('')}</tbody></table></div></div>`;
  const P=D.proj, yrs=['FY25A','FY26E','FY27E','FY28E','FY29E','FY30E','FY31E','FY32E','FY33E','FY34E','FY35E'];
  chart('c-proj',{type:'bar',data:{labels:yrs,datasets:[{label:'Adj. EBITDA',data:P['Adjusted EBITDA'],backgroundColor:css('--accent')},{label:'Unlevered FCF',data:P['Unlevered free cash flow'],backgroundColor:css('--accent-2')}]},options:baseOpts()});
}

