function go(){ let v=(location.hash||'#brief').slice(1); if(!R[v]) v='brief'; document.querySelectorAll('section.view').forEach(s=>s.classList.toggle('on',s.id==='v-'+v)); document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('on',a.dataset.v===v)); $('#vt').textContent=T[v]; $('#vs').textContent=SUB[v]+' · research checked 2026-10-17'; if(window.lastCockpitView!==v){window.scrollTo(0,0);window.lastCockpitView=v;} const sec=$('#v-'+v); if(!sec.dataset.done){R[v](); sec.dataset.done=1;} try{localStorage.setItem('cdv',v);}catch(e){} }
