const evidence=f=>`<span class="evidence ${f.verified?'checked':'pending'}">${f.verified?'Reviewed source':'Reference · review pending'}</span>`;
function logo(id,name,sm){const aliases={bank_jago:'jago',bintang_kecil:'bintang-kecil',shopee:'shopee',tk_UBER:'uber',SE:'sea'};const a=D.logoAssets[id]||D.logoAssets[aliases[id]];return a?.path?`<span class="logo real${sm?' sm':''}" title="${esc(name)}"><img src="${esc(a.path)}" alt="${esc(name)} logo" loading="lazy"></span>`:`<span class="logo unbranded${sm?' sm':''}" title="No verified official logo recorded"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" style="width:16px;height:16px"><path d="M4 21V5h16v16M8 9h2m4 0h2M8 13h2m4 0h2M9 21v-4h6v4"/></svg></span>`}
function mechanism(f){if(f.how)return f.how;const c=(f.category+' '+f.title+' '+f.entity).toLowerCase();if(/treasury|cancel|share count/.test(c))return 'Share cancellation changes the legal capital record. Reconcile issued and outstanding shares before updating EPS or per-share valuation; already-held treasury shares are not new cash.';if(/commission|goride|regulat/.test(c))return 'Product-level pricing and take rate flow into ODS revenue and EBITDA. Incentive offsets, volumes and scope determine the effect; a policy headline alone does not establish the earnings change.';if(/lending|fintech|profitability|sea|monee/.test(c))return 'Distribution, credit growth and funding costs affect net revenue and risk-adjusted profit. Compare borrower mix, loss provisions and cost of funds before transferring a peer multiple to GoTo.';if(/econom|inflation|rate|rupiah|macro/.test(c))return 'Demand, funding costs and FX pass through to transaction volume, credit quality and discount rates. Test the relevant model input instead of assuming a one-to-one share-price effect.';if(/portfolio/.test(c))return 'A company operating milestone may affect adoption or commercial traction. Portfolio value changes require ownership, financial and valuation evidence; a fund-linked company is not automatically a direct GoTo investment.';if(/competitor/.test(c))return 'The move may change distribution, customer acquisition cost or capability gaps. Estimate Indonesia exposure and execution timing before treating regional growth as local market-share loss.';return 'Connect the development to its affected business, revenue or cost driver, timing and evidence. Financial impact remains a scenario until operating data supports it.'}
function feedItem(f){return `<div class="item${isHi(f)&&f.verified?' hi':''}"><div class="d">${esc(f.date)}${/^Review date/.test(f.dateBasis||'')?'<small style="display:block">Review date · statement period shown in source</small>':''}<div style="margin-top:6px">${evidence(f)}</div></div><div><div class="meta">${sev(f.severity)}<span>${esc(f.category)}</span><span>·</span><span>${esc(f.entity)}</span></div><h4>${esc(f.title)}</h4>${signalHoldingNote(f)}<p>${esc(f.summary)}</p>${f.implication?`<div class="imp"><b>Why it matters:</b> ${esc(f.implication)}</div>`:''}<details class="signal-context"><summary>How it matters & next step</summary><div class="imp"><b>Transmission:</b> ${esc(mechanism(f))}</div><div class="imp"><b>Next check:</b> ${esc(f.nextAction||'Verify the original source, reporting scope and latest follow-up before using the signal in a recommendation.')}</div>${f.terms?`<div class="imp"><b>Deal terms:</b> ${esc(f.terms)}</div>`:''}${f.image?.url?`<figure><img class="source-image" src="${esc(f.image.url)}" alt="${esc(f.title)} — source company image" loading="lazy"><figcaption>${esc(f.image.credit)} · original announcement image</figcaption></figure>`:''}</details><div class="meta" style="margin-top:5px">${link(f.url,f.source||'source')}<span>${esc(f.evidence||'Reference research; verify original source')}</span></div></div></div>`}
function signalCompact(f){return f?`<div class="wrow">${logo(compId(f.entity),f.entity,1)}<div><b>${link(f.url,f.title)}</b><p><span class="mono">${esc(f.date)}</span> · ${esc(f.entity)} · ${evidence(f)}</p><p class="signal-why"><strong>So what:</strong> ${esc(f.implication)}</p><details class="signal-context"><summary>How → what to do next</summary><p><strong>How:</strong> ${esc(mechanism(f))}</p><p><strong>Next:</strong> ${esc(f.nextAction)}</p></details></div></div>`:''}
function marketChart(id,tickers,mode='rebased'){const S=D.market.series;tickers=tickers.filter(t=>S[t]?.points.length&&t!=='GOTO');const labels=[...new Set(tickers.flatMap(t=>S[t].points.map(p=>p[0])))].sort();const ds=tickers.map((t,i)=>{const pts=S[t].points,base=pts[0][1],m=Object.fromEntries(pts);return {label:t,data:labels.map(l=>m[l]==null?null:mode==='rebased'?m[l]/base*100:m[l]),borderColor:PAL[i%PAL.length],borderWidth:1.8,pointRadius:0,tension:0,spanGaps:false}});chart(id,{type:'line',data:{labels,datasets:ds},options:baseOpts()})}
function vBriefExisting(){vBriefBaseline();const sec=$('#v-brief');addBriefEvidence();addResearchRadar();const cards=sec.querySelectorAll('.watch>.card');const find=id=>D.feed.find(f=>f.id===id);const riskNames=[['grab','Grab Holdings','Proposed Atome acquisition expands consumer-lending capabilities; banking and payments distribution remain a strategic competitive watch.','Track closing, Indonesia overlap, credit quality and GoPay distribution.'],['monee','Monee','Shopee-linked distribution and a growing credit book put lending capability, funding cost and underwriting at the center of comparison.','Compare loan definitions, cost of funds and loss metrics before applying peer valuations.'],['vinfast','VinFast','An EV ecosystem with hardware and fleet capabilities is relevant to driver economics and Electrum strategy. A specific adverse partnership outcome is not established.','Verify fleet expansion and partnerships; compare driver total cost and infrastructure access.'],['goride','GoRide','The two-wheel commission change affects monetization. Delivery rules remain pending; avoid applying the GoRide cap to every ODS product.','Check Q3 take rate, demand and incentive offsets against the workbook scenarios.']];cards[0].innerHTML=`<h3>High-risk entities <span class="badge">4 high</span></h3>${riskNames.map(([id,name,why,next])=>`<div class="wrow" data-ent="${id}">${logo(id,name,1)}<div><b>${name}<span class="note"> · ${id==='goride'?'core':'competitor'}</span></b><p>${why}</p><details class="signal-context"><summary>How it matters & watch next</summary><p>${next}</p><p class="note">Analyst monitoring priority; not a quantified loss probability. Click the company for evidence.</p></details></div></div>`).join('')}<p class="note"><a href="#competitors">Competitor board →</a> · <a href="#portfolio">Portfolio risk →</a></p>`;const competitive=[find('grab-atome-proposed-20260915'),find('grab-buyback-20260915'),D.feed.find(f=>f.verified&&f.entity==='Sea'&&/grows revenue/i.test(f.title)),D.feed.find(f=>f.verified&&f.entity==='Sea'&&/loan book/i.test(f.title)),D.feed.find(f=>f.verified&&f.entity==='Grab'&&/profitability/i.test(f.title))].filter(Boolean);cards[1].innerHTML=`<h3>High-severity competitor actions <span class="badge">${competitive.length}</span></h3>${competitive.map(signalCompact).join('')}<p class="note"><a href="#competitors">Competitor actions & financials →</a></p>`;const priority=[find('msci-indonesia-consultation-20261015'),find('bi-qris-mdr-oct2026'),find('akulaku-data-misuse-20261015'),find('pathao-cyber-20261008'),find('bintang-exit-review'),find('ojol-operator-response-20261009'),find('goto-egm-outcome-20261014'),find('g6'),find('pluang-agentic-beta-20260925'),find('halodoc-haloassist-20261006'),find('xurya-central-omega-20261001')].filter(Boolean);cards[2].innerHTML=`<h3>High-severity news <span class="badge">${priority.length}</span></h3>${priority.map(signalCompact).join('')}<p class="note"><a href="#feed">Full intelligence feed →</a></p>`;const heading=sec.querySelector('.sec-t');heading.textContent='High-priority watchlist · risk and competitors tagged high';const decisions=sec.querySelectorAll('.decision');const text=[['1 · 14 October EGM: approvals reported','Both agendas are reported approved. Reconcile the correctly dated October minutes and legal capital register before changing the share denominator. Retiring existing treasury shares is not a new cash buyback.'],['2 · GoRide monetization: test the model','The workbook applies the 8% cap to GoRide only. Compare Q3 take rate, volumes and cost offsets with its assumptions; keep delivery rules as a separate pending scenario.'],['3 · Capital allocation: compare competing uses','Compare buybacks, debt reduction, loan-book funding and M&A on expected value creation, liquidity and execution risk. The Rp54 DCF result is a workbook scenario, not proof a buyback wins.'],['4 · Grab–Atome: map the lending overlap','The signed transaction is expected to close by Q3 2027. Track approvals and assess GoPayLater / GoPay Pinjam distribution, underwriting and partnerships before proposing a response.'],['5 · Portfolio: evidence before valuation changes','Moka is group equity through DKAB; Argor is fund exposure. Bintang Kecil historically invested in Xurya and Laku6, with PitchBook reported exits. Reconcile residual holdings and NAV before assigning returns.']];[...decisions].slice(0,text.length).forEach((el,i)=>el.innerHTML=`<b>${text[i][0]}</b><p>${text[i][1]}</p>`);const chartCard=$('#c-brief')?.closest('.card');if(chartCard)chartCard.querySelector('h3').innerHTML='Reviewed peer price history <small>6 months · rebased to each first observed close = 100 · GOTO excluded after data-quality checks</small>';sec.insertAdjacentHTML('beforeend',`<div class="decision evidence-intro"><b>Decision intelligence, with traceable evidence</b><p>Highlighted signals use reviewed sources. Model KPIs come from your valuation workbook; other reference news remains available and labelled for review. ${sheetButton()}</p></div>`);$('#alerts').innerHTML=`● ${D.feed.filter(f=>f.verified&&isHi(f)).length} reviewed priority signals`;}
function workbookTable(name){const sh=sw(name);if(!sh)return '';const header=['Valuation Summary','Comps'].includes(name)?5:name==='Broker Estimates'?2:3;const rows=sh.values.slice(header);const width=Math.max(...rows.map(r=>r.length));return `<div class="tw workbook-tw"><table><thead><tr>${Array.from({length:width},(_,i)=>`<th>${esc(rows[0]?.[i]||'')}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).filter(r=>r.some(v=>v!==null&&v!=='')).map(r=>`<tr>${Array.from({length:width},(_,i)=>`<td class="${i?'r mono':''}">${esc(r[i]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function workbookPreview(defaultTab='Valuation Summary'){return `<div class="card" style="margin-top:14px"><h3>Detailed valuation workbook ${sheetButton()}</h3><p class="note">Model outputs and third-party estimates · snapshot retrieved 13 Oct 2026 · original sharing permissions preserved.</p><select class="search" id="workbookTab" aria-label="Select workbook tab">${WORKBOOK.sheets.map(s=>`<option ${s.title===defaultTab?'selected':''}>${esc(s.title)}</option>`).join('')}</select><div id="workbookSnapshot" style="margin-top:12px">${workbookTable(defaultTab)}</div><details class="signal-context"><summary>Embedded Google Sheets preview (Google sign-in may be required)</summary><iframe id="workbookFrame" title="Detailed GoTo valuation workbook" src="https://docs.google.com/spreadsheets/d/1j8lnnCcCKe3JuD-FdIgaCkIKLDKoouwf2NgsEkXyt2U/preview?rm=minimal&gid=${sw(defaultTab).gid}" loading="lazy"></iframe></details></div>`}
function bindWorkbookPreview(){if($('#workbookTab'))$('#workbookTab').onchange=e=>{$('#workbookSnapshot').innerHTML=workbookTable(e.target.value);$('#workbookFrame').src='https://docs.google.com/spreadsheets/d/1j8lnnCcCKe3JuD-FdIgaCkIKLDKoouwf2NgsEkXyt2U/preview?rm=minimal&gid='+sw(e.target.value).gid}}
function vValBeforeRefresh(){vValBaseline();replaceViewText($('#v-valuation'),'Cap applies to 2-wheel ride-hailing only (Perpres 27/2026). Commission 20%→8% = 60% of GoRide gross revenue lost; 20% opex offset; promotion savings 0.1-0.2% of GTV.','Workbook scenario: prior commission 20%, cap 8%, GoRide exposure, cost offsets and promotion savings are explicit model inputs. Delivery implementation is a separate policy risk.');const section=$('#v-valuation');const broker=section.querySelector('table')?.closest('.card');section.querySelectorAll('.card').forEach(c=>{if(c.querySelector('h3')?.textContent.startsWith('Broker target prices'))c.remove()});section.insertAdjacentHTML('afterbegin',`<div class="decision"><b>Valuation summary · your workbook is the underlying model</b><p>Compare DCF, comps, SOTP and sensitivity outputs below. Open the detailed assumptions, financial statements and broker tables in a separate tab. ${sheetButton()}</p></div>`);section.insertAdjacentHTML('beforeend',`<div class="summary-insight"><div class="card"><h3>Share-count sensitivity</h3><p>Workbook base: 1,154.8bn shares excluding treasury. It also tests a 1,066.1bn alternative. Reconcile the legal register before using per-share outputs.</p>${sheetButton('Open market assumptions',518634861)}</div><div class="card"><h3>What moves the DCF</h3><p>GoRide exposure, monetization offsets, credit economics and the discount rate drive the scenarios. Model outputs do not establish an investment recommendation.</p>${sheetButton('Open detailed DCF',1616707201)}</div><div class="card"><h3>Triangulate the conclusion</h3><p>Compare EV/revenue, EV/adjusted EBITDA, P/E and SOTP. Definitions differ across peers; broker targets have different dates.</p>${sheetButton('Open detailed comps',1178742412)}</div></div>`)}
