function addBriefEvidence(){const reviewed=D.research.filter(r=>r.reviewed);const picks=['ey-sea-financial-ma-h1-2026','curated-038','curated-026','pwc-global-ma-outlook-2026'];const reports=picks.map(id=>reviewed.find(r=>r.id===id)).filter(Boolean);const ties={'ey-sea-financial-ma-h1-2026':'Decision: lending capabilities and partner-versus-acquire options','curated-038':'Decision: acquisition discipline and portfolio exit evidence','curated-026':'Decision: financing conditions and valuation downside','pwc-global-ma-outlook-2026':'Decision: AI capability sourcing and cash allocation'};const next=D.feed.filter(f=>f.verified&&['Economics','Portfolio news'].includes(f.category)).slice(0,4);$('#v-brief').insertAdjacentHTML('beforeend',`<div class="sec-t">Research → decision context</div><div class="grid g2">${reports.map(r=>`<div class="card"><div class="meta"><span class="sev low">${esc(r.type)}</span><span>${esc(r.publisher)} · ${esc(r.date)}</span><span class="evidence checked">Reviewed brief</span></div><h3 style="margin:6px 0">${r.url?link(r.url,r.title):esc(r.title)}</h3><p class="note"><b>${esc(ties[r.id])}</b></p><p class="research-summary">${esc(r.summary)}</p><div class="decision"><b>Why it belongs in this brief</b><p>${esc(r.relevance)}</p></div><details class="signal-context"><summary>Key findings & evidence scope</summary><ul>${(r.takeaways||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="note">${esc(r.evidence)}</p></details><div class="research-links">${r.pdfUrl?link(r.pdfUrl,'Open PDF ↗'):''}<a href="#research">Open research library →</a></div></div>`).join('')}</div><div class="grid g2" style="margin-top:14px"><div class="card"><h3>Intelligence feed → operating assumptions <small>reviewed developments</small></h3>${next.map(feedItem).join('')}<p class="note"><a href="#feed">Explore all ${fmt(D.navigationCounts.feed.count,0)} 2026 signal records →</a></p></div><div class="card"><h3>Decision evidence checklist <small>each implication needs a mechanism</small></h3>${[['Materiality','Which GoTo business, investment position or financing decision is affected?'],['Transmission','Does it change volume, take rate, funding cost, credit losses, share count or valuation assumptions?'],['Timing','Is it reported, proposed, expected or implemented? Which milestone will confirm the effect?'],['Evidence','What has been reviewed? Which claim, number or ownership link still needs confirmation?'],['Alternatives','Compare internal build, partnership, investment, acquisition and capital return before selecting a response.']].map(([title,body])=>`<div class="decision"><b>${title}</b><p>${body}</p></div>`).join('')}<p class="note">${reviewed.length} reviewed research briefs; unreviewed indexed reports and RSS leads are retained as discovery records.</p></div></div>`)}
function vCompBeforeCompetition(){vCompBaseline();const A=D.cact;$('#v-competitors').insertAdjacentHTML('afterbegin',`<div class="decision"><b>Competitor corporate actions · full tracked log</b><p>${A.length} records across ${new Set(A.map(a=>a.company)).size} company labels: acquisitions, disposals, buybacks, funding, banking, governance and partnerships. All tracked actions are shown by default; filter below. Source-reviewed records and reference leads retain their different evidence status.</p></div>`);$('#v-competitors').insertAdjacentHTML('beforeend',`<div class="card" style="margin-top:14px"><h3>Issuer financial and business disclosures <small>Q2 2026 actuals and management guidance</small></h3><p class="note">Currencies, regions and segments differ. Company-defined adjusted EBITDA measures are not automatically comparable; these are not Indonesian market shares.</p><div class="tw"><table><thead><tr><th>Issuer</th><th>Metric / scope</th><th class="r">Value</th><th>Period</th><th>Basis</th></tr></thead><tbody>${VERIFIED.competitorMetrics.map(m=>`<tr><td>${esc(m.company_id.toUpperCase())}</td><td>${esc(m.label)}<div class="note">${esc(m.scope)}${m.note?' · '+esc(m.note):''}</div></td><td class="r mono">${Array.isArray(m.value)?m.value.map(x=>fmt(x)).join('–'):fmt(m.value,m.value<10?1:0)} ${esc(m.unit)}</td><td>${esc(m.period)}</td><td>${m.kind==='management_guidance'?'Management guidance':'Reported actual'}</td></tr>`).join('')}</tbody></table></div><p class="note">${link('https://investors.grab.com','Grab IR')} · ${link('https://www.sea.com/investor/home','Sea IR')}</p></div>`)}
function vIRBeforeRefresh(){vIRBaseline();$('#v-ir').insertAdjacentHTML('beforeend',`<div class="card" style="margin-top:14px"><h3>Public news-discovery feeds <small>RSS retrieval · 13 Oct 2026</small></h3><p class="note">Feeds surface new article leads. Headlines are filtered for company relevance and remain unreviewed until the source is checked; they do not automatically become priority decisions.</p><div class="tw"><table><thead><tr><th>Watch</th><th>Retrieval</th><th>Relevant leads</th><th>Source</th></tr></thead><tbody>${(D.rssFeeds||[]).map(f=>`<tr><td>${esc(f.entity)}</td><td>${esc(f.retrievedAt)}</td><td>${f.relevantRecords??f.items}</td><td>${link(f.url,'Open RSS source ↗')}</td></tr>`).join('')}</tbody></table></div></div>`);$('#v-ir').innerHTML=$('#v-ir').innerHTML.replace('The monitor checks these pages weekly for new filings (results, presentations, shareholder lists, disclosures) and diffs them against the last run.','The separate weekly chat monitor reviews public disclosures. This website contains a dated collection of source links and research; it does not silently publish updates.')}
function paragraphs(text){return String(text||'Not established in this record.').split(/\s\|\s/).map(t=>`<p>${esc(t)}</p>`).join('')}
function profileSection(label,body,caption=''){return `<section class="profile-section"><h3>${label}</h3>${caption?`<p class="note">${esc(caption)}</p>`:''}<div class="profile-copy">${body}</div></section>`}
function renderProfile({id,name,subtitle,tabs,actions=''}){const root=$('#drawer');root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label',name+' company profile');$('#dpanel').innerHTML=`<div class="profile-head"><div class="profile-heading">${logo(id,name)}<div><span class="profile-eyebrow">COMPANY WORKSPACE</span><h2>${esc(name)}</h2><p>${esc(subtitle)}</p></div><button class="btn profile-close" data-close aria-label="Close company profile">✕</button></div><div class="profile-actions">${actions}<button class="btn" data-print-profile>Print tab / PDF ↗</button><button class="btn" id="profileSave">☆ Watch company</button></div></div><nav class="profile-tabs" role="tablist" aria-label="Company profile sections">${tabs.map(([key,label],i)=>`<button role="tab" data-profile-tab="${key}" id="tab-${key}" aria-controls="panel-${key}" aria-selected="${!i}" class="${i?'':'on'}">${label}</button>`).join('')}</nav><div class="profile-content">${tabs.map(([key,label,content],i)=>`<div role="tabpanel" id="panel-${key}" aria-labelledby="tab-${key}" ${i?'hidden':''}>${content}</div>`).join('')}</div><div class="profile-footer">Source-backed research and attributed analyst screening · private figures may be undisclosed</div>`;root.classList.add('on');renderProfile.observer?.disconnect();renderProfile.observer=new ResizeObserver(entries=>$('#dpanel').style.setProperty('--profile-head-height',entries[0].target.offsetHeight+'px'));renderProfile.observer.observe($('#dpanel .profile-head'));$('#dpanel [data-print-profile]').onclick=printCurrentView;const key='goto-watch-company-'+id;let watched=false;try{watched=localStorage.getItem(key)==='1'}catch{}const save=$('#profileSave');save.textContent=watched?'★ Watching · remove':'☆ Watch company';save.onclick=()=>{watched=!watched;try{localStorage.setItem(key,watched?'1':'0');save.textContent=watched?'★ Watching · remove':'☆ Watch company'}catch{save.textContent='Storage unavailable'}};$('#dpanel').querySelectorAll('[data-profile-tab]').forEach(button=>button.onclick=()=>{$('#dpanel').querySelectorAll('[data-profile-tab]').forEach(b=>{b.classList.toggle('on',b===button);b.setAttribute('aria-selected',String(b===button))});$('#dpanel').querySelectorAll('[role="tabpanel"]').forEach(p=>p.hidden=p.id!=='panel-'+button.dataset.profileTab)});$('#dpanel .profile-close').focus()}
function listingPanel(id){const l=D.publicCharts[id];return l?`<section class="profile-section"><h3>Public-market monitor <span class="sev low">${esc(l.symbol)}</span></h3><p class="note">${esc(l.issuer)}${l.parentChart?' · listed parent, not a separately listed operating product':''}</p><p>${link(tvu(l.symbol),'Open full TradingView chart ↗')} · ${link(l.sourceUrl,'Issuer source')}</p><details id="profileChartToggle" class="signal-context"><summary>Show interactive chart</summary><div id="profileChart" style="height:330px;margin-top:12px"></div></details></section>`:profileSection('Financial visibility','<p>Current standalone financials, private valuation and transaction terms have not been established in this record. Request audited statements and a current capitalization table before investment analysis.')}
function bindProfileChart(id){const l=D.publicCharts[id],toggle=$('#profileChartToggle');if(!l||!toggle)return;toggle.ontoggle=e=>{if(!e.target.open||$('#profileChart').children.length)return;const el=$('#profileChart');el.innerHTML='<div class="tradingview-widget-container" style="height:100%;width:100%"><div class="tradingview-widget-container__widget" style="height:100%;width:100%"></div></div>';const script=document.createElement('script');script.src='https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js';script.async=true;script.textContent=JSON.stringify({autosize:true,symbol:l.symbol,interval:'D',timezone:'Asia/Jakarta',theme:css('--bg')==='#f5f7f6'?'light':'dark',style:'1',locale:'en',allow_symbol_change:true,support_host:'https://www.tradingview.com'});el.firstElementChild.appendChild(script)}}
function profileSignals(name,news=[]){const plain=name.split('(')[0].trim().toLowerCase();const signals=D.feed.filter(f=>f.entity.toLowerCase().includes(plain)||plain.length>4&&f.title.toLowerCase().includes(plain)).slice(0,12);return signals.length?signals.map(feedItem).join(''):news.length?news.slice(0,8).map(n=>`<div class="profile-news"><small class="mono">${esc(n.date)}</small><h3>${link(n.url,n.title)}</h3><p>${esc(n.implication||'Review the development against the strategic relationship and operating assumptions.')}</p></div>`).join(''):'<div class="profile-empty"><b>No matched reviewed signals</b><p>The company remains in the coverage universe. Review its official announcements and validate identity before promoting an RSS match.</p></div>'}
function sourceCards(urls){return [...new Set(urls.filter(u=>/^https?:\/\//.test(u||'')))].map((url,i)=>`<a class="profile-source" href="${esc(url)}" target="_blank" rel="noopener"><span class="source-index">${i+1}</span><div><b>${esc(new URL(url).hostname.replace(/^www\./,''))}</b><small>${esc(url)}</small></div><span>↗</span></a>`).join('')||'<p class="note">No verified public source URL recorded.</p>'}
function profileNote(key){return `<section class="profile-section"><h3>Analyst notes</h3><p class="note">Saved only in this browser. Export or copy them for retention.</p><textarea id="profileNote" rows="6" placeholder="Key question, evidence gap, next step…"></textarea><button class="btn" id="saveProfileNote" style="margin-top:8px">Save notes</button></section>`}
function bindProfileNote(key){try{$('#profileNote').value=localStorage.getItem(key)||''}catch{}$('#saveProfileNote').onclick=()=>{try{localStorage.setItem(key,$('#profileNote').value);$('#saveProfileNote').textContent='Saved'}catch{$('#saveProfileNote').textContent='Storage unavailable'}}}
function openEntity(id){const e=byId[id];if(!e)return;const p=e.profile||{},edges=D.eco.edges.filter(x=>x.from===id||x.to===id);const summary=`${profilePositionSummary(e)}<div class="profile-facts"><div><small>Relationship</small><b>${esc(e.investment?HOLDING_GROUPS[e.investment.group]:(D.eco.categories.find(c=>c.id===e.category)?.name||e.category))}</b></div><div><small>Reported location / domicile</small><b>${esc(e.hq||'Not verified')}</b></div><div><small>Evidence</small><b>${e.verified?'Recorded sources':'Reference profile'}</b></div></div>${profileSection('Business overview',paragraphs(e.desc),e.context?.businessEvidence||'')}${ecosystemProfile(e)}${latestProfileSignal(e)}`;const ownership=`${holdingProfile(e.investment)}${profileSection('Legal / investment relationship',paragraphs(e.relation))}<div class="profile-highlight"><small>Recorded ownership</small><b>${esc(e.ownership||'Not disclosed')}</b></div>${edges.length?profileSection('Connected entities',edges.map(x=>{const other=x.from===id?x.to:x.from;return byId[other]?`<button class="profile-connection" data-ent="${other}"><span>${esc(byId[other].name)}</span><small>${esc(x.type)}${x.stakePct!=null?' · '+x.stakePct+'%':''}${x.asOf?' · '+esc(x.asOf):''}</small><span>↗</span></button>`:''}).join('')):''}${profileSection('Funding context',paragraphs(e.funding||'GoTo-attributable fund NAV and private financials are not disclosed.'))}`;const diligence=profileSection('Monitoring triggers','<ul>'+(e.triggers||[]).map(t=>`<li>${esc(t)}</li>`).join('')+'</ul>')+profileSection('Questions before a recommendation','<ul><li>Validate the current legal entity, ownership and beneficial interest.</li><li>Separate product adoption from revenue, profit and attributable investment returns.</li><li>Check commercial overlap, integration effort and competing uses of capital.</li></ul>')+profileNote('goto-company-note-'+id);renderProfile({id,name:e.name,subtitle:(D.eco.categories.find(c=>c.id===e.category)?.name||e.category),actions:e.domain?link('https://'+e.domain,'Company website ↗'):'',tabs:[['overview','Overview',summary],['signals','Signals',orderedProfileSignals(e.name,e.news,id)],['financials','Financials',companyFinancialSummary(id)+listingPanel(id)+(!['bank_jago','goto','grab','sea','monee','shopee'].includes(id)&&p.riskMonitor?.visibility?profileSection('Disclosure scope',paragraphs(p.riskMonitor.visibility)):'' )],['ownership','Ownership',ownership],['diligence','Diligence',diligence],['sources','Sources',`<div class="profile-highlight"><small>Profile provenance</small><p>${esc(e.verification_note||'User reference; independent review pending.')}</p></div>${sourceCards([...(e.sources||[]),p.website,p.market?.crunchbase,p.leader?.sourceUrl,D.publicCharts[id]?.sourceUrl])}`]]});bindProfileChart(id);bindProfileNote('goto-company-note-'+id);$('#dpanel [data-open-profile-signals]')?.addEventListener('click',()=>$('#dpanel [data-profile-tab=signals]').click())}
function openDeal(i){const d=D.deals[i];if(!d)return;const e=E.find(e=>e.name.split('(')[0].trim().toLowerCase()===d.name.split('(')[0].trim().toLowerCase());const id=e?.id||'deal-'+i;const sourceUrls=(d.src||'').split('\n');const tier=(d.tier||'').replace(/^\d\s*-\s*/,'');const summary=`<div class="profile-facts"><div><small>Proposed route</small><b>${esc(tier)}</b></div><div><small>Screening score</small><b>${fmt(d.score,2)} / 5</b></div><div><small>Availability</small><b>Not established</b></div></div>${profileSection('What the company does',paragraphs(d.what))}<div class="profile-highlight"><small>GoTo investment hypothesis</small>${paragraphs(d.structure)}</div>${profileSection('Key rationale',paragraphs(d.why),'Reference analyst screening; validate company claims and economic assumptions.')}`;const fit=`${profileSection('Fit with GoTo',paragraphs(d.link))}${profileSection('Build, partner, invest or acquire',paragraphs(d.structure))}<div class="score-grid">${[['Strategic fit',d.fit],['Feasibility',d.feas],['Capital cost',d.cost],['Risk',d.risk]].map(([label,v])=>`<div><small>${label}</small><b>${v} <span>/ 5</span></b></div>`).join('')}</div><p class="note">Scores are reference analyst judgments. They do not establish diligence completion, deal availability or verified valuation.</p>`;const finance=listingPanel(id)+profileSection('Operating scale',paragraphs(d.status),'Dated reference research; financial claims require source confirmation.')+profileSection('Indicative capital requirement',paragraphs(d.ticket),'Analyst scenario, not a seller quotation or confirmed transaction price.');const ownership=profileSection('Reference ownership & funding',paragraphs(d.own),'Confirm against the current capitalization table; company-profile funding figures may have older vintages.');const key='goto-deal-note-'+d.name;const diligence=profileSection('Deal progression',`<label class="note" for="dealStage">Your review stage</label><select class="search" id="dealStage"><option>Watchlist</option><option>Researching</option><option>Discuss internally</option><option>Diligence</option><option>Parked</option></select>`)+profileSection('Next diligence steps','<ol><li>Validate ownership, seller intent, financial statements and cash generation.</li><li>Check duplication with GoTo capabilities and existing commercial relationships.</li><li>Assess partner and minority-investment alternatives before control acquisition.</li><li>Review integration, licensing, data access and financing with the relevant teams.</li></ol>')+profileNote(key);renderProfile({id,name:d.name,subtitle:d.theme+' · '+tier,actions:e?.domain?link('https://'+e.domain,'Company website ↗'):'',tabs:[['overview','Overview',summary],['fit','Strategic fit',fit],['signals','Signals',profileSignals(e?.name||d.name,e?.news)],['financials','Financials',finance],['ownership','Ownership',ownership],['diligence','Diligence',diligence],['sources','Sources',sourceCards([...sourceUrls,...(e?.sources||[]),e?.crunchbase])]]});bindProfileChart(id);bindProfileNote(key);try{$('#dealStage').value=localStorage.getItem(key+'-stage')||'Watchlist'}catch{}$('#dealStage').onchange=e=>{try{localStorage.setItem(key+'-stage',e.target.value)}catch{}}}
function addWorkspaceControls(){const status=$('.status');if(!$('#workspaceSearchButton')){status.insertAdjacentHTML('beforeend','<button class="btn" id="workspaceSearchButton" aria-label="Search workspace">⌕ Search <span class="keyhint">⌘K</span></button><button class="btn" id="exportDecisionBrief" title="Print the current page or company tab; save as PDF in your browser">Print page / PDF ↗</button><a class="btn" href="docs/GoTo-CorpDev-Cockpit-Feature-Guide.pdf" target="_blank" rel="noopener">Feature guide PDF ↗</a>');const dialog=document.createElement('dialog');dialog.id='workspaceSearch';dialog.setAttribute('aria-label','Search workspace');dialog.innerHTML='<div class="workspace-search-head"><input id="workspaceQuery" type="search" placeholder="Company, signal, research or action…" aria-label="Search all research"><button class="btn" id="closeWorkspaceSearch">Esc</button></div><div id="workspaceSearchResults"></div>';document.body.appendChild(dialog);const draw=()=>{const q=$('#workspaceQuery').value.toLowerCase();const results=[...E.map(e=>({title:e.name,type:'Company',sub:e.relation,id:e.id})),...D.feed.map(f=>({title:f.title,type:f.verified?'Reviewed signal':'Research lead',sub:f.date+' · '+f.entity,url:f.url})),...D.research.map(r=>({title:r.title,type:r.reviewed?'Reviewed research':'Indexed report',sub:r.publisher+' · '+r.date,url:r.url})),...D.ca.map(a=>({title:a.event,type:'Corporate action',sub:a.date+' · '+a.status,url:a.sources?.find(u=>/^https?:/.test(u))}))].filter(r=>q&&(r.title+' '+r.sub).toLowerCase().includes(q)).slice(0,24);$('#workspaceSearchResults').innerHTML=results.map(r=>r.id?`<button class="workspace-result" data-search-entity="${esc(r.id)}"><span class="sev low">${r.type}</span><div><b>${esc(r.title)}</b><small>${esc(r.sub)}</small></div><span>↗</span></button>`:`<a class="workspace-result" href="${esc(r.url||'#')}" target="_blank" rel="noopener"><span class="sev low">${r.type}</span><div><b>${esc(r.title)}</b><small>${esc(r.sub)}</small></div><span>↗</span></a>`).join('')||'<div class="profile-empty">'+(q?'No matches in the current research snapshot.':'Search company profiles, public updates, reports and corporate actions.')+'</div>';dialog.querySelectorAll('[data-search-entity]').forEach(b=>b.onclick=()=>{dialog.close();openEntity(b.dataset.searchEntity)})};const open=()=>{prepareDashboardDialog(dialog);dialog.showModal();$('#workspaceQuery').value='';draw();$('#workspaceQuery').focus()};$('#workspaceSearchButton').onclick=open;$('#closeWorkspaceSearch').onclick=()=>dialog.close();$('#workspaceQuery').oninput=draw;document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();open()}});$('#exportDecisionBrief').onclick=printCurrentView;}}
addWorkspaceControls();
function companyFinancialSummaryBaseline(id){let metrics=[],source='';if(id==='bank_jago'){metrics=[['Customer deposits','Rp27.6tn'],['Loan disbursements','Rp26.6tn'],['H1 net profit after tax','Rp189bn'],['Gross NPL','0.8%'],['CASA / deposits','53%'],['Capital adequacy','28.4%']];source='https://www.jago.com/en/media-center/press-release/bank-jago-continues-growth-with-solid-fundamentals'}else if(id==='goto'){metrics=VERIFIED.metrics.slice(0,6).map(m=>[m.label,fmt(m.value,m.value<100?1:0)+' '+m.unit]);source='https://gotocompany.com/investor-relations/en'}else if(['grab','sea','monee','shopee'].includes(id)){const issuer=id==='grab'?'grab':'sea';const scope=id==='monee'?'Monee':id==='shopee'?'Shopee':'Group';metrics=VERIFIED.competitorMetrics.filter(m=>m.company_id===issuer&&m.scope===scope&&m.kind!=='management_guidance').slice(0,6).map(m=>[m.label,fmt(m.value,m.value<10?1:0)+' '+m.unit]);source=id==='grab'?'https://investors.grab.com':'https://www.sea.com/investor/home'}if(!metrics.length)return '';return `<section class="profile-section"><h3>Reported financial / operating snapshot <small>${id==='bank_jago'?'H1 2026 · June-end balances':'Q2 2026 · issuer-defined scope'}</small></h3><div class="profile-metrics">${metrics.map(([label,value])=>`<div><small>${esc(label)}</small><b>${esc(value)}</b></div>`).join('')}</div><p class="note">${link(source,'Official issuer source')} · Company-level figures; not automatically GoTo-attributable returns.</p></section>`}

function preparePrintSnapshot(){
  const profile=$('#drawer.on')?$('#dpanel'):null;
  const source=profile||document.querySelector('section.view.on');
  if(!source)return;
  const selected=profile?profile.querySelector('[data-profile-tab].on')?.textContent:source.querySelector('[role=tab][aria-selected=true]')?.textContent;
  const title=(profile?profile.querySelector('h2')?.textContent:$('#vt').textContent)+(selected?' - '+selected:'');
  $('#printSnapshot')?.remove();
  const doc=document;const snapshot=doc.createElement('div');snapshot.id='printSnapshot';
  snapshot.dataset.originalTitle=doc.title;doc.title='GoTo Cockpit - '+title;
  const header=doc.createElement('header');header.className='print-heading';
  header.innerHTML='<img src="assets/logos/goto.svg" alt="GoTo"><div><small>CORPORATE DEVELOPMENT COCKPIT</small><h1>'+esc(title)+'</h1><p>Research checked: '+esc(D.as_of)+' - source dates and evidence labels retained</p></div>';
  const clone=source.cloneNode(true);clone.classList.add('print-content');
  const originals=source.querySelectorAll('canvas');clone.querySelectorAll('canvas').forEach((c,i)=>{
    const img=doc.createElement('img');img.className='print-chart';img.alt='Chart from '+title;
    try{if(chartQueue.has(originals[i].id)){c.replaceWith(doc.createTextNode('Chart is loading. Use Print page / PDF in the dashboard to prepare all charts before exporting.'));return}img.src=originals[i].toDataURL('image/png');c.replaceWith(img)}catch{c.replaceWith(doc.createTextNode('Interactive provider chart: open the live dashboard to view.'))}
  });
  const fields=source.querySelectorAll('input,select,textarea');clone.querySelectorAll('input,select,textarea').forEach((field,i)=>{
    const label=doc.createElement('span');label.className='print-filter';
    label.textContent=(fields[i].getAttribute('aria-label')||fields[i].getAttribute('placeholder')||'Selection')+': '+(fields[i].tagName==='SELECT'?fields[i].selectedOptions[0]?.textContent:fields[i].value||'All');field.replaceWith(label)
  });
  clone.querySelectorAll('iframe').forEach(frame=>{const note=doc.createElement('p');note.className='note';note.innerHTML='External interactive view: '+link(frame.src,'Open detailed source in your browser');frame.replaceWith(note)});
  clone.querySelectorAll('script,.profile-close,#profileSave,[data-print-profile],.profile-tabs,button:not(.company-link):not(.profile-connection):not(.ownership-node):not(.ownership-connection)').forEach(n=>n.remove());
  const footer=doc.createElement('footer');footer.className='print-footer';footer.innerHTML='Current page / selected tab with current filters. '+link(location.href,'Open this dashboard view')+'<br>Independent public-source analysis. Reviewed evidence, reference research and RSS leads remain distinct. External interactive charts may require the live page.';
  snapshot.append(header,clone,footer);doc.body.append(snapshot);
}
async function printCurrentView(){await prepareCurrentCharts();preparePrintSnapshot();window.print()}
window.addEventListener('beforeprint',()=>{if(!$('#printSnapshot'))preparePrintSnapshot()});

window.addEventListener('afterprint',()=>{const snapshot=$('#printSnapshot');if(snapshot){document.title=snapshot.dataset.originalTitle;snapshot.remove()}Object.values(charts).forEach(c=>c.resize())});

const HOLDING_GROUPS={'direct-subsidiary':'Direct GoTo subsidiaries','vehicle-subsidiary':'Subsidiaries through group vehicles','other-consolidated':'Other consolidated entities','associate':'Strategic associate equity','bintang-equity':'Bintang Kecil · corporate equity','fund-manager':'Fund manager','fund-exposure':'GoTo fund exposure','fund-portfolio':'Argor portfolio examples','fund-history':'Historical Argor portfolio leads','legacy-equity':'Historical equity / refresh needed','divested':'Former / divested assets','unresolved-equity':'Equity / partner relationship unconfirmed'};
function holdingBadge(r){return `<span class="holding-badge ${/fund/.test(r.group)?'fund':r.group==='bintang-equity'?'bintang':''}">${esc(HOLDING_GROUPS[r.group])}</span>`}
function holdingEvidence(r){return `<span class="evidence ${r.reviewed?'checked':'pending'}">${r.reviewed?'Reviewed evidence':'Research lead'}</span>`}
function capitalRoutes(){const pick=ids=>ids.map(id=>D.portfolioRegister.records.find(r=>r.id===id)).filter(Boolean);const node=r=>`<button class="capital-node" data-ent="${r.id}">${logo(r.id,r.name,1)}<span><b>${esc(r.name)}</b><small>${r.stakePct!=null?esc(r.stakePct+'% effective · '):''}${esc(r.exitDate?'Reported exit '+r.exitDate:r.group==='fund-portfolio'?'Fund / current stake undisclosed':r.status)}</small></span><span>↗</span></button>`;return `<div class="capital-hub">${logo('goto','GoTo',1)}<b>GoTo Group</b><span class="note">Follow the legal route before assigning value or control</span></div><div class="capital-grid"><section class="capital-lane"><div class="capital-lane-head"><span>01 · GROUP EQUITY</span><h3>Control & strategic stakes</h3><p>Operating results, associate earnings and shareholder rights</p></div><div class="capital-path">GoTo → DKAB / SBR / other vehicles</div>${pick(['dkab','moka','midtrans','gopay','tokopedia','bank_jago','bridestory']).map(node).join('')}<a href="#portfolio" data-register-open data-register-scope="legal">51 subsidiaries + 11 other consolidated entities →</a></section><section class="capital-lane bintang"><div class="capital-lane-head"><span>02 · CORPORATE VEHICLE</span><h3>Bintang Kecil equity</h3><p>Historical company stakes held through a group vehicle</p></div><div class="capital-path">GoTo → SBR → Bintang Kecil</div>${pick(['bintang_kecil','xurya','laku6']).map(node).join('')}<div class="capital-foot">PitchBook reports exits for both companies. Current residual stakes and exit proceeds need reconciliation. Bridestory’s older Bintang route is recorded separately.</div></section><section class="capital-lane fund"><div class="capital-lane-head"><span>03 · FUND EXPOSURE</span><h3>Argor-managed funds</h3><p>Fund capital accounts, commitments, distributions and NAV</p></div><div class="capital-path">GoTo fund backing → managed funds → companies</div>${pick(['argor','argor-funds','pluang','halodoc','ai-hay','pickup-coffee','seindonesia']).map(node).join('')}<div class="capital-foot">Portfolio examples are not direct GoTo stakes. Allocation to Fund I / II and attributable NAV are undisclosed.</div></section></div>`}
function holdingProfile(r){if(!r)return '';return profileSection('Capital route',`<div class="profile-highlight">${holdingBadge(r)}<p><b>${esc(r.route)}</b></p><p>${holdingEvidence(r)} · ${esc(r.status)}</p><small>${esc(r.asOf)}</small></div><dl class="kv"><dt>Legal identity</dt><dd>${esc(r.legalName)}</dd><dt>Accounting / control</dt><dd>${esc(r.accounting)}</dd><dt>Stake definition</dt><dd>${esc(r.stakeBasis)}</dd>${r.carryingIdrMillion!=null?`<dt>Carrying value</dt><dd>Rp${fmt(r.carryingIdrMillion/1000,1)}bn · ${esc(r.carryingAsOf||'30 Jun 2026')} · accounting value</dd>`:''}${r.exitDate?`<dt>Reported exit</dt><dd>${esc(r.exitDate)} · PitchBook · residual holding unconfirmed</dd>`:''}</dl><p class="note">${esc(r.sourceNote)}</p>${r.routeScope?`<p class="note">${esc(r.routeScope)}</p>`:''}${r.evidenceImage?`<details class="signal-context"><summary>View supplied PitchBook evidence</summary><a href="${esc(r.evidenceImage)}" target="_blank" rel="noopener"><img class="source-image" src="${esc(r.evidenceImage)}" alt="User supplied PitchBook Bintang Kecil historical investments" loading="lazy"></a></details>`:''}`)+profileSection('What this relationship means',paragraphs(r.why))+profileSection('Monitor the actual economic position',paragraphs(r.monitor))}
function holdingRow(r){const news=D.feed.find(f=>f.verified&&(f.entity.toLowerCase()===r.name.toLowerCase()||r.id==='xurya'&&f.entity==='Xurya'));return `<tr><td><button class="company-link" data-ent="${r.id}">${logo(r.id,r.name,1)}<b>${esc(r.name)}</b></button><div class="note">${esc(r.legalName)}</div></td><td>${holdingBadge(r)}<p class="note">${esc(r.route)}</p></td><td class="mono">${r.stakePct==null?'Undisclosed':r.stakePct+'%'}<div class="note">${r.stakePct==null?'Current ownership unavailable':'Effective / reported stake'}</div>${r.carryingIdrMillion!=null?`<div class="note">Book: Rp${fmt(r.carryingIdrMillion/1000,1)}bn</div>`:''}</td><td>${holdingEvidence(r)}<p>${esc(r.status)}</p><small class="mono">${esc(r.asOf)}</small>${r.exitDate?`<p class="down">Reported exit ${esc(r.exitDate)}</p>`:''}</td><td>${news?`<small class="mono">${esc(news.date)}</small><p>${link(news.url,news.title)}</p>`:'<span class="note">No reviewed company update matched</span>'}${r.exitDate?'<p class="note">Operating news does not prove a retained GoTo interest.</p>':''}<details class="signal-context"><summary>Why / monitor next</summary><p>${esc(r.why)}</p><p>${esc(r.monitor)}</p></details></td><td>${link(r.sourceUrl,'Source ↗')}<p class="note">${esc(r.sourceNote)}</p><button class="btn" data-ent="${r.id}">Open company →</button></td></tr>`}
function renderPortfolioWorkspace(){const pack=D.portfolioRegister;$('#v-portfolio').innerHTML=`<div class="decision"><b>Own the company, invest through a vehicle, or back a fund?</b><p>The route determines control, economics and the diligence required. This register separates current disclosed entities, historical company investments and indirect fund exposure.</p></div><div class="grid g3"><div class="card kpi"><span class="l">Disclosed group subsidiaries</span><span class="v">51</span><span class="s">17 direct + 34 indirect · June 2026</span></div><div class="card kpi"><span class="l">Other consolidated entities</span><span class="v">11</span><span class="s">Control judgments · ownership percentages not itemized</span></div><div class="card kpi"><span class="l">Argor attributable NAV</span><span class="v" style="font-size:20px">Undisclosed</span><span class="s">Manager AUM $400m is a separate metric</span></div></div><div class="sec-t">Ownership & investment routes</div>${capitalRoutes()}<div class="grid g2" style="margin-top:16px"><div class="card"><h3>Where the accounting value sits <small>30 Jun 2026 · IDR billion</small></h3>${pack.aggregates.map(a=>`<div class="holding-value"><span>${esc(a.label)}<small>${esc(a.basis)}</small></span><b class="mono">${fmt(a.value/1000,1)}</b></div>`).join('')}<p class="note">Carrying amounts, not market valuations or invested cost. Subsidiary assets are excluded to avoid double-counting consolidated entities. ${link(pack.sources[0],'Financial statement notes ↗')}</p></div><div class="card"><h3>Signals that change the portfolio decision</h3>${[['Xurya / Laku6 · reconcile exits','PitchBook reports Xurya exit on 8 Jun 2024 and Laku6 on 26 Jul 2022. Verify proceeds and residual interests before marking either as an active investment.'],['Bintang Kecil · reconcile identity','PitchBook labels the investor inactive; GoTo still lists the Singapore entity under SBR in June 2026. Investor activity, legal existence and beneficial ownership are separate questions.'],['Moka · operating value','99.99% effective subsidiary through DKAB. Monitor merchant adoption, payment attachment and contribution to consolidated earnings.'],['Argor funds · look through with evidence','Track portfolio funding and news, but request fund-level NAV, unfunded commitments, distributions and investment schedules before computing GoTo returns.']].map(([title,text])=>`<div class="decision"><b>${title}</b><p>${text}</p></div>`).join('')}</div></div><div class="sec-t">Position register · filter by ownership route</div><div class="feed-toolbar"><input class="search" type="search" id="holdingSearch" placeholder="Company, legal entity or holding vehicle…" aria-label="Search investment register"><select class="search" id="holdingGroup" aria-label="Filter investment route"><option value="focus">Strategic & investment positions</option><option value="all">All disclosed / researched positions</option>${Object.entries(HOLDING_GROUPS).map(([id,name])=>`<option value="${id}">${esc(name)}</option>`).join('')}</select><span class="note" id="holdingCount"></span><button class="btn" id="exportHoldings">Export register ↓</button></div><div class="card"><div class="tw holding-table"><table><thead><tr><th>Company / legal entity</th><th>Ownership route</th><th>Stake / book value</th><th>Status / vintage</th><th>News → decision</th><th>Evidence</th></tr></thead><tbody id="holdingRows"></tbody></table></div></div><details class="signal-context" style="margin-top:16px"><summary>Coverage limits and diligence standards</summary><ul>${pack.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><div class="sec-t">Operating developments across the investment network</div><div class="card">${D.feed.filter(f=>f.verified&&f.category==='Portfolio news').map(feedItem).join('')}</div>`;const draw=()=>{const q=$('#holdingSearch').value.toLowerCase(),group=$('#holdingGroup').value;const rows=pack.records.filter(r=>(group==='all'||(group==='focus'?!['direct-subsidiary','vehicle-subsidiary','other-consolidated'].includes(r.group)||['moka','dkab','sbr','bintang_kecil','bridestory'].includes(r.id):r.group===group))&&[r.name,r.legalName,r.route,r.status].join(' ').toLowerCase().includes(q));$('#holdingCount').textContent=rows.length+' positions';$('#holdingRows').innerHTML=rows.map(holdingRow).join('')||'<tr><td colspan="6">No matching positions. Try another company or ownership route.</td></tr>'};$('#holdingSearch').oninput=draw;$('#holdingGroup').onchange=draw;draw();$('#exportHoldings').onclick=()=>{const cols=['name','legalName','group','route','stakePct','stakeBasis','asOf','status','exitDate','carryingIdrMillion','sourceUrl','sourceNote','monitor'];const csv=cols.join(',')+'\n'+pack.records.map(r=>cols.map(k=>'"'+String(r[k]??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='GoTo-investment-route-register-2026-10-13.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
