function signalHoldingNote(f){const r=D.portfolioRegister.records.find(r=>r.name.toLowerCase()===f.entity.toLowerCase());return r?`<div class="signal-holding">${holdingBadge(r)} <span class="note">${esc(r.exitDate?'Reported exit '+r.exitDate+' · residual stake unconfirmed':r.group==='fund-portfolio'?'Fund allocation and current stake undisclosed':r.status)}</span></div>`:''}

