const dailyTradingView=(symbol)=>({autosize:true,symbol,interval:'D',timezone:'Asia/Jakarta',theme:css('--bg')==='#f5f7f6'?'light':'dark',style:'1',locale:'en',allow_symbol_change:true,support_host:'https://www.tradingview.com'});
function mountDailyChart(el,symbol){
  el.innerHTML='<div class="tradingview-widget-container" style="height:100%;width:100%"><div class="tradingview-widget-container__widget" style="height:100%;width:100%"></div></div>';
  const script=document.createElement('script');script.src='https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js';script.async=true;script.textContent=JSON.stringify(dailyTradingView(symbol));el.firstElementChild.appendChild(script);
}
function bindProfileChart(id){const l=D.publicCharts[id],toggle=$('#profileChartToggle');if(l&&toggle)toggle.ontoggle=e=>{if(e.target.open&&!$('#profileChart').children.length)mountDailyChart($('#profileChart'),l.symbol)}}
function workbookNumber(value){
  if(value==null||value==='')return null;if(typeof value==='number')return value;
  let raw=String(value).trim(),negative=/^\(.*\)$/.test(raw);raw=raw.replace(/^Rp\s*/,'').replace(/[()%x]/g,'').replace(/\s/g,'');
  if(!/^[+-]?[\d.,]+$/.test(raw))return null;
  // The supplied sheet uses Indonesian thousands separators and decimal commas.
  raw=raw.includes(',')?raw.replaceAll('.','').replace(',','.'):raw.replaceAll('.','');
  const n=Number(raw);return Number.isFinite(n)?(negative?-n:n):null;
}
function workbookValue(value){
  if(value==null||value==='')return '—';const raw=String(value);
  if(raw.length>45||/^\d{4}-\d{2}-\d{2}$/.test(raw))return esc(raw);
  const n=workbookNumber(value);if(n===null)return esc(raw==='n.m.'?'N/M':raw);
  const decimals=raw.includes(',')?Math.min(2,(raw.split(',')[1].match(/^\d+/)?.[0]||'').length):0;
  const result=fmt(Math.abs(n),decimals)+(raw.includes('%')?'%':/x$/.test(raw)?'×':'');
  return (raw.startsWith('Rp')?'Rp':'')+(n<0?'('+result+')':result);
}
function peers(){return sw('Comps').values.slice(6,13).map((r,i)=>({r,i,name:r[0],ticker:r[1],currency:r[2],asOf:r[3],priceCurrency:r[1]==='3690.HK'?'HKD':r[2]==='IDR bn'?'IDR':r[2],financialUnit:r[2]==='IDR bn'?'IDR billion':r[2]+' million'}))}
function peerDetail(p){const r=p.r;return `<div class="comps-detail"><p><b>${esc(p.name)}</b> · price in ${esc(p.priceCurrency)}; financial values in ${esc(p.financialUnit)} · quote ${esc(p.asOf)}</p><div class="profile-metrics">${[[5,'Market capitalization'],[6,'Enterprise value'],[7,'FY2025 revenue'],[8,'FY2026E revenue'],[9,'FY2025 EBITDA'],[10,'FY2026E EBITDA'],[12,'FY2026E net income'],[11,'5-year levered beta']].map(([i,label])=>`<div><small>${label}${i===11?'':' · '+esc(p.financialUnit)}</small><b>${workbookValue(r[i])}</b></div>`).join('')}</div><p class="note">${p.ticker==='NU'?'Banking business: debt and deposits are operating items; EV/EBITDA is not a suitable banking comparison.':p.ticker==='3690.HK'?'Meituan trades in HKD; the workbook financial values have been converted to CNY.':p.ticker==='BUKA.JK'?'Negative enterprise value makes EV multiples non-meaningful; cash and operating prospects need separate review.':'Company-defined EBITDA measures and regional business mixes differ.'} Estimates are the workbook’s dated third-party consensus inputs. ${sheetButton('Open source comps',sw('Comps').gid)}</p></div>`}
function compsSummary(){const med=sw('Comps').values[14];return `<div class="comps-summary"><div class="grid g3">${[[13,'Median EV / sales'],[14,'Median EV / EBITDA'],[15,'Median P / E']].map(([i,label])=>`<div class="mini-metric"><small>${label} · FY2026E</small><b>${workbookValue(med[i])}</b></div>`).join('')}</div><p class="note">Seven workbook peers · quoted 30 Sep–12 Oct 2026 · forecasts, not reported actuals. Medians retain the workbook’s inclusion rules; N/M means not meaningful.</p><div class="tw readable-table"><table><thead><tr><th>Company / quote date</th><th class="r">Price</th><th class="r">EV / sales<br><small>FY2026E</small></th><th class="r">EV / EBITDA<br><small>FY2026E</small></th><th class="r">P / E<br><small>FY2026E</small></th><th>Details</th></tr></thead><tbody>${peers().map(p=>`<tr><td><b>${esc(p.name)}</b><small class="table-sub">${esc(p.ticker)} · ${esc(p.asOf)}</small></td><td class="r mono">${workbookValue(p.r[4])}<small class="table-sub">${esc(p.priceCurrency)}</small></td><td class="r mono">${workbookValue(p.r[13])}</td><td class="r mono">${workbookValue(p.r[14])}</td><td class="r mono">${workbookValue(p.r[15])}</td><td><button class="btn" data-peer-detail="${p.i}" aria-expanded="false">Expand</button></td></tr><tr data-peer-row="${p.i}" hidden><td colspan="6">${peerDetail(p)}</td></tr>`).join('')}</tbody></table></div><details class="signal-context"><summary>Definitions and comparability</summary><p>EV = enterprise value; P/E = price to earnings. Financial values use each company’s stated currency and scale. Meituan’s trading price is HKD, while its model financials are CNY million. Banking, negative EV and loss-making companies require different methods. Open the source workbook for beta calculations and segment SOTP.</p></details></div>`}
function bindPeerDetails(root=document){root.querySelectorAll('[data-peer-detail]').forEach(b=>b.onclick=()=>{const row=root.querySelector('[data-peer-row="'+b.dataset.peerDetail+'"]');row.hidden=!row.hidden;b.setAttribute('aria-expanded',String(!row.hidden));b.textContent=row.hidden?'Expand':'Collapse'})}
function workbookRows(name){const s=sw(name);const index={'Valuation Summary':5,'Comps':5,'IS Detail':3,'BS Detail':3,'CF Detail':3,'2Q26 Reconciliation':3,'FS Data (as filed)':3,'Corporate Actions':3,'Broker Estimates':4}[name];return s.values.slice(index??3)}
function tableFromRows(rows,mode='focus',query=''){
  const header=rows[0]||[];
  let cols=header.map((v,i)=>v!=null&&v!==''?i:null).filter(i=>i!==null);
  if(!cols.includes(0))cols.unshift(0);
  if(mode==='focus'&&cols.length>6){
    const recent=cols.filter(i=>i&&/^(1Q26|2Q26|1H2026|FY2025$|FY25$|Dec-25|Jun-26|Mar-26|3M26|6M26)/.test(header[i]));
    cols=recent.length?[0,...recent.slice(-4)]:cols.slice(0,5);
  }
  return `<div class="tw readable-table"><table><thead><tr>${cols.map(i=>`<th class="${i?'r':''}">${esc(header[i]||'Line item')}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).filter(r=>r.some(v=>v!=null&&v!=='')&&(!query||String(r[0]||'').toLowerCase().includes(query))).map(r=>{const heading=r.slice(1).every(v=>v==null||v==='');return heading?`<tr class="workbook-section"><th colspan="${cols.length}">${esc(r[0])}</th></tr>`:`<tr><td><span class="row-label">${esc(r[0]||'Supporting value')}</span></td>${cols.slice(1).map(i=>`<td class="r ${workbookNumber(r[i])==null?'':'mono'}">${workbookValue(r[i])}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>`;
}
function workbookTable(name,mode='focus',query=''){
  if(name==='Comps')return compsSummary();
  const rows=workbookRows(name);
  if(name==='FS Data (as filed)')return '<p>The source filing tab contains separate income statement, balance-sheet and cash-flow sections. Use the statement tabs for readable period labels, or open the original sheet for its complete YTD source data.</p><div class="research-links">'+sheetButton('Open as-filed source',sw(name).gid)+'</div>';
  if(['DCF','Market Valuation'].includes(name)){
    const selected=name==='DCF'?sw(name).values.slice(4,31):rows;
    const values=selected.filter(r=>r[0]&&r[1]!=null&&r[1]!==''&&(!query||String(r[0]).toLowerCase().includes(query)));
    return `<p class="note">Dated model assumptions and outputs · full forecasts and sensitivities open in the source sheet.</p><div class="tw readable-table"><table><thead><tr><th>Assumption / output</th><th class="r">Input / model output</th><th>Context</th></tr></thead><tbody>${values.slice(0,mode==='focus'?24:200).map(r=>`<tr><td>${esc(r[0])}</td><td class="r mono">${workbookValue(r[1])}</td><td>${esc(r[12]||r[6]||'')}</td></tr>`).join('')}</tbody></table></div>`;
  }
  if(name==='Broker Estimates')return `<div class="tw readable-table"><table><thead><tr><th>Source / date</th><th>View</th><th class="r">Target price</th><th class="r">Previous target</th><th>Basis</th></tr></thead><tbody>${sw(name).values.slice(5,10).map(r=>`<tr><td><b>${esc(r[0])}</b><small class="table-sub">${esc(r[1])}</small></td><td>${esc(r[2])}</td><td class="r mono">${workbookValue(r[3])}</td><td class="r mono">${workbookValue(r[5])}</td><td class="comps-basis">${esc(r[12])}</td></tr>`).join('')}</tbody></table></div><p class="note">Historical price targets and model scenarios, not current recommendations. Open the original workbook for group forecasts and cap-impact bridges.</p>`;
  if(name==='Corporate Actions')return `<p>Use the dedicated corporate-actions workspace for searchable event details, evidence and implications.</p><a class="btn" href="#actions">Open corporate actions →</a>`;
  return tableFromRows(rows,mode,query);
}
function workbookPreview(defaultTab='IS Detail'){return `<div class="card workbook-workspace" style="margin-top:14px"><h3>Financial workbook <small>readable snapshot · detailed source opens separately</small>${sheetButton()}</h3><p class="note">IDR billion unless stated · comma = thousands, dot = decimals · parentheses = negative · E/F = forecast. Quarterly statements and FY / half-year periods are distinct.</p><div class="workbook-controls"><label>Statement / model<select class="search" id="workbookTab" aria-label="Select workbook tab">${WORKBOOK.sheets.map(s=>`<option ${s.title===defaultTab?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label>Columns<select class="search" id="workbookMode" aria-label="Workbook columns"><option value="focus">Recent / summary</option><option value="all">All source periods</option></select></label><label>Find line item<input type="search" class="search" id="workbookLineSearch" aria-label="Find workbook line item" placeholder="Revenue, cash, profit…"></label><a class="btn" id="workbookSourceTab" target="_blank" rel="noopener" href="${SHEET}#gid=${sw(defaultTab).gid}">Open selected sheet ↗</a></div><div id="workbookSnapshot">${workbookTable(defaultTab)}</div></div>`}
function bindWorkbookPreview(){const select=$('#workbookTab');if(!select)return;const draw=()=>{$('#workbookSnapshot').innerHTML=workbookTable(select.value,$('#workbookMode').value,$('#workbookLineSearch').value.toLowerCase());$('#workbookSourceTab').href=SHEET+'#gid='+sw(select.value).gid;bindPeerDetails($('#workbookSnapshot'))};select.onchange=()=>{$('#workbookLineSearch').value='';draw()};$('#workbookMode').onchange=draw;$('#workbookLineSearch').oninput=draw;draw()}
function marketChart(id,tickers){
  const series=D.market.series;tickers=tickers.filter(t=>series[t]?.points.length);
  const start=tickers.map(t=>series[t].points[0][0]).sort().at(-1),end=tickers.map(t=>series[t].points.at(-1)[0]).sort()[0];
  const colors={GOTO:'#35d09b',JKSE:'#ffbd59',GRAB:'#08a979',SE:'#45a9ed',UBER:'#b890ff',ARTO:'#f37780'};
  chart(id,{type:'line',data:{datasets:tickers.map((t,i)=>{const points=series[t].points.filter(p=>p[0]>=start&&p[0]<=end),base=points[0][1];return {label:t==='JKSE'?'IDX Composite (IHSG)':t,data:points.map(([date,value])=>({x:Date.parse(date+'T00:00:00Z'),y:value/base*100})),borderColor:colors[t]||PAL[i%PAL.length],borderWidth:['GOTO','JKSE'].includes(t)?2.8:1.6,pointRadius:0,tension:0}})},options:baseOpts({parsing:false,plugins:{legend:{labels:{color:css('--muted'),boxWidth:12}},tooltip:{callbacks:{title:items=>new Date(items[0].parsed.x).toISOString().slice(0,10),label:c=>c.dataset.label+': '+fmt(c.parsed.y,1)}}},scales:{x:{type:'linear',min:Date.parse(start),max:Date.parse(end),ticks:{color:css('--muted'),maxTicksLimit:7,callback:v=>new Date(v).toLocaleDateString('en-GB',{month:'short',day:'numeric',timeZone:'UTC'})},grid:{color:css('--line')}},y:{ticks:{color:css('--muted')},grid:{color:css('--line')}}}})});
  const parent=document.getElementById(id)?.closest('.card');if(parent&&!parent.querySelector('.comparison-basis'))parent.insertAdjacentHTML('beforeend',`<p class="note comparison-basis">${esc(start)} → ${esc(end)} · each first observed close = 100 · daily closes, local currency, no dividends or FX adjustment. GOTO / IDX benchmark included; source: Yahoo Finance. The comparison ends at the common completed daily session; ticker-strip quotes can include newer intraday observations. ${link('https://finance.yahoo.com/quote/GOTO.JK/history/','GOTO history ↗')} · ${link('https://finance.yahoo.com/quote/%5EJKSE/history/','IDX history ↗')}</p>`);
}
