 return '<div class="ux-workspace-bar"><div class="ux-workspace-actions">'+(views.length?'<select class="search ux-saved-select" aria-label="Saved '+scope+' views" data-ux-saved-scope="'+scope+'"><option value="">Saved views</option>'+views.map(v=>uxOption(v.id,v.name,'')).join('')+'</select>':'')+uxButton('Save view','view-save',scope)+uxButton(uxStore.pins.includes(scope==='customers'?'sentiment':scope)?'★ Pinned':'☆ Pin page','pin',scope)+'</div></div>';
