 return D.feed.filter(f=>f.verified&&f.date>=cutoff&&(uxBrief.segment==='all'||CI.services.some(s=>s.segment===uxBrief.segment&&ciRelevant(f,s)&&(ciOwnMatch(f,s)||s.peers.some(p=>ciMatch(f,p.brand)))))&&(uxBrief.updates==='all'||!uxStore.lastSeen||uxBrief.updates==='new'&&f.date>uxDate(uxStore.lastSeen)||uxBrief.updates==='updated'&&f.date<=uxDate(uxStore.lastSeen)&&Date.parse(f.reviewedAt||f.date)>Date.parse(uxStore.lastSeen))).sort((a,b)=>String(b.reviewedAt||b.date).localeCompare(String(a.reviewedAt||a.date))||b.date.localeCompare(a.date));
