  root.insertAdjacentHTML('beforeend','<div class="ux-results-line"><b>'+rows.length+' companies</b><span>Public profile vintages retained; transaction availability is unverified.</span></div><div class="ux-table-wrap"><table class="ux-table"><thead><tr><th>Company</th><th>Market / capability</th><th>Potential GoTo relevance</th><th>Evidence</th></tr></thead><tbody>'+dbPageRows(rows,uxDeals.page).map(d=>{const key=uxKey(global?'global':'deal',d);return '<tr><td><button class="ux-company-link" data-ux-action="evidence" data-ux-key="'+esc(key)+'">'+(byId[d.id]?ciLogo(d.id):uxDealLogo(d))+'<b>'+esc(d.name)+'</b></button></td><td>'+esc(d.country||'Not supplied')+'<small>'+esc(d.cat||d.theme||d.sector||'')+'</small></td><td>'+esc((d.use||d.fit||d.description||'Review capability fit').slice(0,220))+'</td><td>'+uxButton('Review','evidence',key)+'</td></tr>'}).join('')+'</tbody></table></div>'+dbPager(rows.length,uxDeals.page,'deals'));
