function uxNav(){
 const nav=$('#nav');if(!nav)return;const anchors=new Map([...nav.querySelectorAll('a[data-v]')].map(a=>[a.dataset.v,a])),help=$('#coverageCountsHelp'),groups=[['Brief',['brief']],['Competitors & customers',['competitors','sentiment','global']],['GoTo & ownership',['financials','actions','ecosystem','portfolio']],['Markets & valuation',['markets','macro','policy','valuation']],['Deals',['deals']],['Research',['feed','research','ir']]];
 nav.replaceChildren();if(uxStore.pins.length){const title=document.createElement('div');title.className='grp';title.textContent='PINNED';nav.append(title);uxStore.pins.forEach(id=>{const source=anchors.get(id);if(source){const a=source.cloneNode(true);a.classList.add('ux-pinned-link');nav.append(a)}})}
 groups.forEach(([name,ids])=>{const group=document.createElement('details');group.className='ux-nav-group';group.open=uxStore.navClosed?.includes(name)?false:true;const summary=document.createElement('summary');summary.textContent=name;group.append(summary);ids.forEach(id=>{if(anchors.has(id))group.append(anchors.get(id))});group.addEventListener('toggle',()=>{uxStore.navClosed=(uxStore.navClosed||[]).filter(x=>x!==name);if(!group.open)uxStore.navClosed.push(name);uxWrite()});nav.append(group)});
 if(help)nav.append(help);uxOpenActiveNav();
}
