function uxMatrixMetric(id,pattern){
 const issuer=['sea','shopee','shopeefood','shopeepay','monee','seabank','spaylater','spinjam'].includes(id)?'sea':id;
 const metric=id==='goto'?VERIFIED.metrics.find(m=>m.period==='Q2 2026'&&pattern.test(m.label)):VERIFIED.competitorMetrics.find(m=>m.company_id===issuer&&m.period==='Q2 2026'&&m.scope==='Group'&&m.kind==='reported_actual'&&pattern.test(m.label));
 if(!metric)return '<span class="note">No matched Q2 group metric collected. This is a coverage gap, not a zero.</span>';
 const scopeLabel=issuer!==id?'Sea Group · parent context for '+ciName(id):(metric.scope||metric.definition||'Consolidated');
 const source=(VERIFIED.sources||[]).find(s=>s.id===(metric.sourceId||metric.source_id)),r={id:'metric-'+id+'-'+metric.label,title:(issuer!==id?'Sea Group (parent of '+ciName(id)+')':ciName(id))+' · '+metric.label,date:source?.publication_date||source?.date||'2026-Q2',publisher:source?.publisher||ciName(id),type:'Reported financial metric',url:metric.sourceUrl||source?.url,summary:metric.label+': '+fmt(metric.value,1)+' '+metric.unit+'. Period: '+metric.period+'. Scope: '+scopeLabel+'.',relevance:'Compare reporting definitions and currency before inferring a relative valuation or operating advantage.',evidence:source?.evidence||'Recorded issuer metric; definition and period retained.',reviewed:true};
 return '<strong>'+fmt(metric.value,1)+' '+esc(metric.unit)+'</strong><small>'+esc(metric.label)+' · '+esc(scopeLabel)+' · '+esc(metric.period)+'</small>'+uxButton('Source','evidence',uxKey('research',r));
}
