 if(tab==='profile')body=`<div class="gb-profile-intro">${gbLogo(p)}<div>${gbBadge(p.reviewClass,p.reviewed?'reviewed':'')}<p>${esc(p.description)}</p></div></div><div class="gb-detail-grid"><section><h3>Business model</h3><p>${esc(p.model||p.role)}</p><h3>What GoTo can learn</h3><p>${esc(p.insight||p.gotoRelevance||'Research thesis not yet established.')}</p><h3>Innovation to examine</h3><p>${esc(p.innovation||'Use sourced updates and case studies to examine specific innovations; no validated innovation claim in this profile yet.')}</p></section><section><h3>Ownership & legal identity</h3><p>${esc(p.parent||'Parent not established')}</p><p>${esc(p.entityType)}</p><small>${esc(p.parentStatus)} · ${esc(p.relation)}</small><h3>Research scope</h3><p>${esc(p.evidenceScope)}</p><p>${esc(p.unknowns)}</p></section></div><div class="gb-detail-stats">${gbButton(ms.length+' market links','company-tab',id+'|markets')}${gbButton(us.length+' sourced updates','company-tab',id+'|updates')}${gbButton(es.length+' capital events','company-tab',id+'|capital')}</div><h3>Sources behind this profile</h3>${(p.sources||[]).map((u,i)=>`<p>${gbSource(u,'Source '+(i+1))}</p>`).join('')}<p class="gb-small">Profile review: ${esc(p.reviewedDate||p.checkedDate||'Not independently reviewed')}. A website lead is not verification of ownership or every market.</p>`;
 if(tab==='markets')body=`<p class="gb-map-note">Each row is a product-country research association. Read its evidence scope before treating it as an active licensed service.</p><div class="ux-table-wrap"><table class="ux-table"><thead><tr><th>Country / category</th><th>Product / evidence</th><th>Source</th></tr></thead><tbody>${dbPageRows(ms,gbDetailPage).map(m=>`<tr><td><b>${esc(m.country)}</b><small>${esc(m.category)}</small></td><td>${esc(m.product)}<small>${esc(m.verification)}</small><p>${esc(m.scope)}</p></td><td>${gbSource(m.sourceUrl)}<small>${esc(m.sourceDate||m.checkedDate||'Source date not established')}</small></td></tr>`).join('')}</tbody></table></div>${dbPager(ms.length,gbDetailPage,'profile')}`;
