function gbPriceTrend(){const a=D.market?.series?.GOTO?.points,b=D.market?.series?.JKSE?.points;if(!a?.length||!b?.length)return '';const start=Math.max(Date.parse(a[0][0]),Date.parse(b[0][0])),end=Math.min(Date.parse(a.at(-1)[0]),Date.parse(b.at(-1)[0])),rows=[a,b].map(points=>points.filter(([d,v])=>Date.parse(d)>=start&&Date.parse(d)<=end&&Number.isFinite(v)));if(rows.some(r=>!r.length))return '';const norm=rows.map(ps=>ps.map(([d,v])=>[d,100*v/ps[0][1]])),all=norm.flat().map(p=>p[1]),lo=Math.floor(Math.min(...all)/20)*20,hi=Math.ceil(Math.max(...all)/20)*20,y=v=>96-(v-lo)/(hi-lo||1)*78,x=d=>22+(Date.parse(d)-start)/(end-start||1)*310;return {svg:`<svg viewBox="0 0 360 125" role="img" aria-label="GoTo and IDX Composite performance, first observed close equals100">${[lo,(lo+hi)/2,hi].map(v=>`<line x1="22" x2="335" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="18" y="${y(v)+3}" text-anchor="end" fill="var(--muted)" font-size="8">${v}</text>`).join('')}${norm.map((ps,i)=>`<path d="${ps.map(([d,v],j)=>(j?'L':'M')+x(d).toFixed(1)+','+y(v).toFixed(1)).join(' ')}" stroke="${i?'#c68a2b':'var(--accent)'}" stroke-width="2" fill="none"/>`).join('')}<text x="22" y="116" fill="var(--muted)" font-size="10">${new Date(start).toISOString().slice(0,10)}</text><text x="335" y="116" text-anchor="end" fill="var(--muted)" font-size="10">${new Date(end).toISOString().slice(0,10)}</text></svg>`,returns:norm.map(ps=>ps.at(-1)[1]-100),end:new Date(end).toISOString().slice(0,10)}}
