function miScopeRelationships(){const services=miData.services.filter(s=>miState.segment==='all'||s.segment===miState.segment).map(s=>s.id);return miData.relationships.filter(r=>(miState.platform==='all'||r.platformId===miState.platform||[r.fromId,r.toId].some(id=>id===miState.platform||miEntity(id)?.groupId===miState.platform))&&(miState.segment==='all'||services.includes(r.sectorId))&&(miState.service==='all'||r.sectorId===miState.service)&&(miState.relation==='all'||r.internalExternal===miState.relation)&&(!miState.query||[miName(r.fromId),miName(r.toId),r.relationType,r.description].join(' ').toLowerCase().includes(miState.query.toLowerCase())))}
function miField(id,label,options,value){return `<label class="mi-field">${label}<select id="${id}" data-mi-filter="${id.replace('miFilter','').toLowerCase()}">${options.map(([k,v])=>`<option value="${esc(k)}"${value===k?' selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
function miFilters(){return `<div class="mi-platforms" role="group" aria-label="Platform ecosystem">${miButton('<span class="mi-cross-mark">◎</span><span>Cross-platform</span>','platform','all','mi-platform '+(miState.platform==='all'?'on':''))}${miPlatforms().map(p=>miButton(miLogo(p.id)+'<span>'+esc(p.name)+'</span>','platform',p.id,'mi-platform '+(miState.platform===p.id?'on':''))).join('')}</div><div class="mi-filterbar"><div class="mi-segment-switch" role="group" aria-label="Business segment">${[['all','All services'],['ods','ODS'],['finance','Financial services']].map(([k,v])=>`<button data-mi-action="segment" data-mi-key="${k}" aria-pressed="${miState.segment===k}">${v}</button>`).join('')}</div>${miField('miFilterService','Service layer',[['all','All service layers'],...miData.services.filter(s=>miState.segment==='all'||s.segment===miState.segment).map(s=>[s.id,s.title])],miState.service)}${miField('miFilterRelation','Relationship',[['all','All documented links'],['internal','Internal service'],['external','External relationship'],['affiliate','Affiliate / associate']],miState.relation)}<label class="mi-field mi-search">Find company or provider<input id="miQuery" type="search" value="${esc(miState.query)}" placeholder="GoSend, Jago, SPX…"></label>${miButton('Reset','reset')}</div>`}
function miSelectDefault(rows){if(!rows.length){miState.selected=null;return}if(!miState.selected||!rows.some(r=>r.id===miState.selected))miState.selected=rows.find(r=>r.internalExternal==='external')?.id||rows[0].id}
function miBindFilters(){document.querySelectorAll('#v-competitors [data-mi-filter]').forEach(el=>el.onchange=()=>{miState[el.dataset.miFilter]=el.value;miState.page=1;miState.selected=null;miRender()});uxLiveSearch('miQuery',value=>{miState.query=value;miState.page=1;miRender()})}
function miRender(){
 if(!miData)return;for(const id of miChartKeys){charts[id]?.destroy();delete charts[id]}miChartKeys=[];
 const root=$('#v-competitors');if(miState.view==='signals'){renderCompetition();return}
 const content=miState.view==='ecosystem'?miEcosystem():miState.view==='markets'?miMarkets():miPerformance();root.innerHTML=miShell()+content;
 if(miState.view==='ecosystem'){miBindFilters();miBindMap()}
 if(miState.view==='markets'){miBindFilters();miPaintMarkets();}if(miState.view==='performance')miPaintPerformance();
}
function miEcosystem(){const rows=miScopeRelationships().filter(r=>['flow','grouped'].includes(miState.layout)&&miState.platform!=='all'?r.platformId===miState.platform:true);miSelectDefault(rows);const providers=new Set(rows.filter(r=>r.internalExternal!=='internal').map(r=>r.toId)),shared=[...providers].filter(id=>new Set(miData.relationships.filter(r=>r.toId===id).map(r=>r.platformId)).size>1);return `${mlFiltersForLayout()}<div class="mi-map-toolbar"><div><b>${miState.platform==='all'?'Cross-platform connections':esc(miName(miState.platform))+' ecosystem'}</b><span>${miState.layout==='events'?mlEventRows().length+' sourced company events · original status and reporting scope retained':rows.length+' documented relationships · '+providers.size+' partner endpoints · '+shared.length+' shared across platforms'}</span></div><div class="mi-map-tabs" role="group" aria-label="Ecosystem visualization">${[['network','Network'],['grouped','Platform groups'],['flow','Supply chain'],['matrix','Service heatmap'],['providers','Shared providers'],['events','Events & links'],['table','Table']].map(([k,v])=>`<button data-mi-action="layout" data-mi-key="${k}" aria-pressed="${miState.layout===k}">${v}</button>`).join('')}</div></div>${!rows.length?'<div class="gb-empty"><h3>No documented links match</h3><p>Broaden the filters to explore the source-backed network.</p>'+miButton('Clear filters','reset')+'</div>':miState.layout==='network'?`<div class="mi-map-workspace"><div class="mi-graph-panel"><div class="mi-graph-legend"><span><i class="internal"></i>Internal service</span><span><i class="external"></i>External relationship</span><span><i class="affiliate"></i>Affiliate / associate</span><div>${miButton('−','zoom-out','','mi-map-control')}${miButton('Fit','fit','','mi-map-control')}${miButton('+','zoom-in','','mi-map-control')}</div></div><div class="mi-graph-viewport" id="miGraphViewport" tabindex="0" aria-label="Commercial ecosystem graph; scroll to explore"><div id="miGraphStage">${miNetwork(rows)}</div></div><div class="mi-graph-caption">Select a node or connection to inspect its evidence. Connections describe relationships; line width does not represent transaction volume.</div></div><aside class="mi-inspector" id="miInspector" aria-label="Selected relationship">${miInspector(rows.find(r=>r.id===miState.selected))}</aside></div>`:miState.layout==='grouped'?mlGrouped(rows):miState.layout==='flow'?mlFlow(rows):miState.layout==='events'?mlEvents():miState.layout==='matrix'?miMatrix(rows):miState.layout==='providers'?miProviderHeatmap(rows):miRelationshipTable(rows)}<div class="mi-bottom-note"><span class="mi-evidence-dot"></span>Commercial relationships are separate from ownership. Listed availability can depend on city, order, product and eligibility. Provider allocation and financial impact are not publicly quantified unless explicitly reported.</div>${miData.coverageGaps?.length?'<details class="mi-coverage-notes"><summary>Coverage & interpretation</summary><ul>'+miData.coverageGaps.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul></details>':''}`}
function miNetwork(rows){
 const idset=new Set(rows.flatMap(r=>[r.fromId,r.toId]));if(miState.platform!=='all')idset.add(miState.platform);
 const nodes=[...idset].map(miEntity).filter(Boolean),columns=[nodes.filter(e=>e.kind==='platform'),nodes.filter(e=>!['platform','external_provider','affiliate'].includes(e.kind)),nodes.filter(e=>['external_provider','affiliate'].includes(e.kind))];
 const active=rows.find(r=>r.id===miState.selected),positions=new Map(),nodeW=180,nodeH=57,gap=15;let height=Math.max(...columns.map(c=>c.length),1)*72+80,width=830;
 columns.forEach((col,i)=>{col.sort((a,b)=>{const da=rows.filter(r=>r.fromId===a.id||r.toId===a.id).length,db=rows.filter(r=>r.fromId===b.id||r.toId===b.id).length;return db-da||a.name.localeCompare(b.name)});col.forEach((e,j)=>positions.set(e.id,{x:28+i*285,y:i===0&&col.length===1?Math.max(58,(height-nodeH)/2):58+j*(nodeH+gap)}))});
 const edges=rows.map(r=>{const a=positions.get(r.fromId),b=positions.get(r.toId);if(!a||!b)return '';const forward=b.x>a.x,x1=a.x+(forward?nodeW:nodeW/2),x2=b.x+(forward?0:nodeW/2),y1=a.y+nodeH/2,y2=b.y+nodeH/2,path=forward?`M${x1},${y1} C${(x1+x2)/2},${y1} ${(x1+x2)/2},${y2} ${x2},${y2}`:`M${x1},${y1} C${x1+130},${y1} ${x2+130},${y2} ${x2},${y2}`;return `<g class="mi-edge ${esc(r.internalExternal)} ${r.id===miState.selected?'selected':''}" role="button" tabindex="0" data-mi-edge="${esc(r.id)}" aria-label="${esc(miName(r.fromId)+' to '+miName(r.toId)+': '+r.relationType)}"><path class="mi-edge-hit" d="${path}"/><path class="mi-edge-line" d="${path}"/><title>${esc(r.relationType+' · '+r.status)}</title></g>`}).join('');
 return `<div class="mi-network-canvas" style="width:${width}px;height:${height}px"><svg width="${width}" height="${height}" aria-label="Source-backed commercial links">${edges}</svg>${['PLATFORMS','PRODUCTS & OPERATING SERVICES','EXTERNAL PROVIDERS & AFFILIATES'].map((label,i)=>`<span class="mi-graph-column" style="left:${28+i*285}px">${label}</span>`).join('')}${nodes.map(e=>{const p=positions.get(e.id),degree=rows.filter(r=>r.fromId===e.id||r.toId===e.id).length,selected=active&&(active.fromId===e.id||active.toId===e.id);return `<button class="mi-node ${esc(e.kind)} ${selected?'connected':''}" style="left:${p.x}px;top:${p.y}px;width:${nodeW}px;height:${nodeH}px" data-mi-node="${esc(e.id)}" aria-pressed="${Boolean(selected)}" title="${esc(e.description||e.name)}">${miLogo(e.id)}<span><b>${esc(e.name)}</b><small>${e.kind==='platform'?'Platform':e.kind==='affiliate'?'Associate / partner':e.kind==='external_provider'?'External provider':'Operating service'}</small></span><em>${degree}</em></button>`}).join('')}</div>`;
}
function miInspector(r){if(!r)return '';const from=miEntity(r.fromId),to=miEntity(r.toId),linked=miData.relationships.filter(e=>e.toId===r.toId),platforms=[...new Set(linked.map(e=>e.platformId))];return `<div class="mi-inspector-top"><span class="ux-eyebrow">RELATIONSHIP INTELLIGENCE</span>${miButton('Full details ↗','relationship',r.id,'mi-detail-link')}</div><div class="mi-connection-pair"><div>${miLogo(from.id)}<b>${esc(from.name)}</b></div><span>→</span><div>${miLogo(to.id)}<b>${esc(to.name)}</b></div></div><span class="mi-relation-pill ${esc(r.internalExternal)}">${esc(r.relationType)}</span><p class="mi-inspector-summary">${esc(r.description)}</p><div class="mi-inspector-fact"><small>SOURCE STATUS</small><b>${esc(r.status)}</b><span>Checked ${esc(r.checkedAt)}</span></div>${r.transmission?`<div class="mi-transmission"><small>HOW CHANGE COULD TRAVEL</small><p>${esc(r.transmission)}</p></div>`:''}${r.watchMetric?`<div class="mi-watch-metric"><small>WATCH NEXT</small><b>${esc(r.watchMetric)}</b></div>`:''}${platforms.length>1?`<section class="mi-shared"><h4>Shared provider · ${platforms.length} ecosystems</h4><div>${platforms.map(id=>miButton(miLogo(id)+'<span>'+esc(miName(id))+'</span>','platform',id,'mi-shared-platform')).join('')}</div></section>`:''}<div class="mi-inspector-source">${miSource(r.sourceUrl,r.sourceName||'Company documentation')}${miButton('Read evidence here','relationship',r.id,'mi-detail-link')}</div>`}
function miHeatLevel(count,max){return count?Math.min(5,Math.max(1,Math.ceil(Math.log2(count+1)/Math.log2(max+1)*5))):0}
function miHeatLegend(){return '<div class="mi-heat-legend"><span>Documented links</span><i class="level-0"></i><small>Not mapped</small><i class="level-1"></i><i class="level-2"></i><i class="level-3"></i><i class="level-4"></i><i class="level-5"></i><small>More links</small><b>Coverage ≠ market share or relationship strength</b></div>'}
function miHeatInsights(rows){const external=rows.filter(r=>r.internalExternal!=='internal'),shared=miSharedRows(rows),sectors=new Set(rows.map(r=>r.sectorId));return `<div class="mi-heat-insights"><article><span>COMMERCIAL REACH</span><b>${external.length}<small>external & affiliate links</small></b><div class="mi-insight-track"><i style="width:${rows.length?external.length/rows.length*100:0}%"></i></div></article><article><span>SHARED DISTRIBUTION</span><b>${shared.length}<small>providers across 2+ ecosystems</small></b><div class="mi-insight-logos">${shared.slice(0,6).map(p=>miLogo(p.id)).join('')}</div></article><article><span>SERVICE COVERAGE</span><b>${sectors.size}<small>service layers with evidence</small></b><p>Select a colored cell to read the supporting connections.</p></article></div>`}
function miSharedRows(rows){const targets=[...new Set(rows.map(r=>r.toId))].filter(id=>miEntity(id)?.kind!=='platform');return targets.map(id=>({id,platforms:[...new Set(rows.filter(r=>r.toId===id).map(r=>r.platformId))]})).filter(p=>p.platforms.length>1).sort((a,b)=>b.platforms.length-a.platforms.length||miName(a.id).localeCompare(miName(b.id)))}
function miHeatHead(platforms,label){return `<thead><tr><th>${label}</th>${platforms.map(p=>`<th>${miLogo(p.id)}<b>${esc(p.name)}</b></th>`).join('')}</tr></thead>`}
function miMatrix(rows){const platforms=miPlatforms(),sectors=miData.services.filter(s=>rows.some(r=>r.sectorId===s.id)),max=Math.max(1,...sectors.flatMap(s=>platforms.map(p=>rows.filter(r=>r.platformId===p.id&&r.sectorId===s.id).length)));let segment='';return `${miHeatInsights(rows)}<div class="mi-matrix-intro"><div><span class="ux-eyebrow">PLATFORM × SERVICE</span><h3>Where ecosystems connect</h3></div><span>Shade shows the number of source-backed relationships in this registry. Each cell separates internal services from external or affiliate partners.</span></div>${miHeatLegend()}<div class="ux-table-wrap mi-matrix-wrap mi-heat-wrap"><table class="mi-matrix mi-heatmap">${miHeatHead(platforms,'Service layer')}<tbody>${sectors.sort((a,b)=>a.segment.localeCompare(b.segment)||miData.services.indexOf(a)-miData.services.indexOf(b)).map(s=>{let heading='';if(segment!==s.segment){segment=s.segment;heading=`<tr class="mi-heat-group"><th colspan="${platforms.length+1}">${segment==='finance'?'FINANCIAL SERVICES':'ON-DEMAND SERVICES & COMMERCE'}</th></tr>`}return heading+`<tr><th><span>${esc(s.title)}</span><small>${rows.filter(r=>r.sectorId===s.id).length} documented links</small></th>${platforms.map(p=>{const found=rows.filter(r=>r.platformId===p.id&&r.sectorId===s.id),internal=found.filter(r=>r.internalExternal==='internal').length,partner=found.length-internal;return `<td>${found.length?miButton(`<strong>${found.length}</strong><span>${internal?'I '+internal:''}${internal&&partner?' · ':''}${partner?'P '+partner:''}</span>`,'heat-cell',p.id+'|'+s.id,'mi-matrix-cell mi-heat-cell level-'+miHeatLevel(found.length,max)):'<span class="mi-heat-empty" title="No relationship documented in this registry">—</span>'}</td>`}).join('')}</tr>`}).join('')}</tbody></table></div><p class="mi-heat-foot">I = internal service · P = external or affiliate partner. A blank cell means not yet documented here; it does not establish absence or inactivity.</p>`}
function miProviderHeatmap(rows){const platforms=miPlatforms(),providers=miSharedRows(rows),max=Math.max(1,...providers.flatMap(p=>platforms.map(platform=>rows.filter(r=>r.toId===p.id&&r.platformId===platform.id).length)));return `${miHeatInsights(rows)}<div class="mi-matrix-intro"><div><span class="ux-eyebrow">PROVIDER × PLATFORM</span><h3>Who serves more than one ecosystem?</h3></div><span>Shared providers can connect competing platforms. This view identifies documented routes, without inferring exclusivity or how orders and payment volumes are allocated.</span></div>${miHeatLegend()}${providers.length?`<div class="ux-table-wrap mi-matrix-wrap mi-heat-wrap"><table class="mi-matrix mi-heatmap">${miHeatHead(platforms,'Shared provider / product')}<tbody>${providers.map(p=>`<tr><th><div class="mi-inline-brand">${miLogo(p.id)}<span><b>${esc(miName(p.id))}</b><small>${p.platforms.length} ecosystems</small></span></div></th>${platforms.map(platform=>{const n=rows.filter(r=>r.toId===p.id&&r.platformId===platform.id).length;return `<td>${n?miButton(`<strong>${n}</strong><span>${n===1?'link':'links'}</span>`,'provider-cell',platform.id+'|'+p.id,'mi-matrix-cell mi-heat-cell level-'+miHeatLevel(n,max)):'<span class="mi-heat-empty">—</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="gb-empty"><h3>No shared providers match these filters</h3><p>Choose all services or reset the filters to explore the cross-platform network.</p></div>'}<p class="mi-heat-foot">Counts are documented relationship types, not provider volumes, customer counts or financial exposure.</p>`}
function miOpenHeatCell(key,provider=false){const[platform,id]=key.split('|'),rows=miScopeRelationships().filter(r=>r.platformId===platform&&(provider?r.toId===id:r.sectorId===id)),title=provider?miName(id):miData.services.find(s=>s.id===id)?.title||id;gbOpenDialog(miName(platform)+' × '+title,'HEATMAP · SOURCE-BACKED CONNECTIONS',`<div class="mi-heat-reader"><div class="mi-heat-reader-summary">${miLogo(platform)}<div><b>${rows.length} documented ${rows.length===1?'relationship':'relationships'}</b><p>Internal services, external partnerships and affiliates retain their original source scope.</p></div></div>${rows.map(r=>`<article class="mi-heat-evidence"><div class="mi-inline-brand">${miLogo(r.fromId)}<b>${esc(miName(r.fromId))}</b><span>→</span>${miLogo(r.toId)}<b>${esc(miName(r.toId))}</b></div><span class="mi-relation-pill ${esc(r.internalExternal)}">${esc(r.relationType)}</span><p>${esc(r.description)}</p><div>${miSource(r.sourceUrl,r.sourceName)}${miButton('Connection details →','relationship',r.id,'mi-detail-link')}</div></article>`).join('')}${miButton('Explore this network →',provider?'provider-network':'matrix-cell',key)}</div>`)}
function miRelationshipTable(rows){return `<div class="ux-table-wrap"><table class="ux-table mi-relationship-table"><thead><tr><th>Platform</th><th>Connection</th><th>Type & status</th><th>Evidence</th></tr></thead><tbody>${dbPageRows(rows,miState.page).map(r=>`<tr><td><div class="mi-inline-brand">${miLogo(r.platformId)}<b>${esc(miName(r.platformId))}</b></div></td><td><button class="ux-title-button" data-mi-action="relationship" data-mi-key="${esc(r.id)}">${esc(miName(r.fromId))} → ${esc(miName(r.toId))}</button><small>${esc(r.description)}</small></td><td><span class="mi-relation-pill ${esc(r.internalExternal)}">${esc(r.relationType)}</span><small>${esc(r.status)}</small></td><td>${miSource(r.sourceUrl,r.sourceName)}<small>Checked ${esc(r.checkedAt)}</small></td></tr>`).join('')}</tbody></table></div>${miPager(rows.length,miState.page)}`}
function miPager(count,page){const pages=Math.max(1,Math.ceil(count/20));return `<div class="db-pagination"><p>${count?((page-1)*20+1)+'–'+Math.min(page*20,count):0} of ${count} relationships</p><div><button class="btn" data-mi-action="page" data-mi-key="${page-1}" ${page<=1?'disabled':''}>← Previous</button><span>Page ${page} / ${pages}</span><button class="btn" data-mi-action="page" data-mi-key="${page+1}" ${page>=pages?'disabled':''}>Next →</button></div></div>`}
function miBindMap(){const viewport=$('#miGraphViewport'),stage=$('#miGraphStage');if(!viewport||!stage)return;const fit=()=>viewport.clientWidth<600?1:Math.max(.8,Math.min(1,(viewport.clientWidth-20)/830));if(miState.zoom===1)miState.zoom=fit();stage.style.zoom=miState.zoom;const applySelected=id=>{miState.selected=id;$('#miInspector').innerHTML=miInspector(miData.relationships.find(r=>r.id===id));viewport.querySelectorAll('.mi-edge').forEach(e=>e.classList.toggle('selected',e.dataset.miEdge===id));const r=miData.relationships.find(r=>r.id===id);viewport.querySelectorAll('.mi-node').forEach(e=>{const yes=[r?.fromId,r?.toId].includes(e.dataset.miNode);e.classList.toggle('connected',yes);e.setAttribute('aria-pressed',String(yes))})};viewport.querySelectorAll('[data-mi-edge]').forEach(e=>{e.onclick=()=>applySelected(e.dataset.miEdge);e.onkeydown=ev=>{if(['Enter',' '].includes(ev.key)){ev.preventDefault();applySelected(e.dataset.miEdge)}}});viewport.querySelectorAll('[data-mi-node]').forEach(e=>e.onclick=()=>miInspectNode(e.dataset.miNode));let drag=null;viewport.onpointerdown=e=>{if(e.target.closest('button,[data-mi-edge]'))return;drag={x:e.clientX,y:e.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};viewport.setPointerCapture(e.pointerId)};viewport.onpointermove=e=>{if(drag){viewport.scrollLeft=drag.left-(e.clientX-drag.x);viewport.scrollTop=drag.top-(e.clientY-drag.y)}};viewport.onpointerup=()=>drag=null;}
function miOpenRelationship(id){const r=miData.relationships.find(r=>r.id===id);if(!r)return;gbOpenDialog(miName(r.fromId)+' → '+miName(r.toId),'DOCUMENTED COMMERCIAL RELATIONSHIP',`<div class="mi-relationship-reader">${miInspector(r)}<section><h3>Exact relationship scope</h3><p>${esc(r.scope||r.description)}</p></section><div class="mi-reader-measures"><article><small>PROVIDER ALLOCATION</small><b>Not publicly disclosed</b></article><article><small>QUANTIFIED FINANCIAL IMPACT</small><b>${esc(r.impact||'Not publicly quantified')}</b></article></div><section><h3>Evidence</h3><p>Relationship source checked ${esc(r.checkedAt)}${r.sourcePublishedAt?' · original source '+esc(r.sourcePublishedAt):''}. Listed integration does not establish exclusivity, volumes, current licence status or control.</p>${miSource(r.sourceUrl,r.sourceName)}<div>${miButton('Preview original in dashboard','preview',r.sourceUrl)}</div><div id="miSourcePreview"></div></section></div>`)}
function miMetricList(){return miData.metrics.filter(m=>(miState.marketsector==='all'||m.sectorId===miState.marketsector)&&(miState.segment==='all'||(miState.segment==='ods'?['ecommerce','ride','car','food','parcel','grocery','freight','ev'].includes(m.sectorId):!['ecommerce','ride','car','food','parcel','grocery','freight','ev'].includes(m.sectorId))))}
/* Market layouts loaded below. */
function miChart(id,type,labels,datasets,extra={}){const color=getComputedStyle(document.documentElement).getPropertyValue('--muted').trim()||'#8ba097',line=getComputedStyle(document.documentElement).getPropertyValue('--line').trim()||'#35483c';miChartKeys.push(id);const base={responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:datasets.length>1,position:'bottom',labels:{color,usePointStyle:true,boxWidth:9,font:{size:11}}},tooltip:{callbacks:{label:c=>c.dataset.label+': '+Number(c.raw).toLocaleString('en-US',{maximumFractionDigits:2})+(extra.suffix||'')}}},scales:{x:{beginAtZero:true,ticks:{color,font:{size:11}},grid:{display:false}},y:{beginAtZero:true,ticks:{color,font:{size:10}},grid:{color:line}}}};const overrides=extra.options||{},options={...base,...overrides,scales:{...base.scales}};for(const key of Object.keys(overrides.scales||{}))options.scales[key]={...base.scales[key],...overrides.scales[key]};options.plugins={...base.plugins,...overrides.plugins};chart(id,{type,data:{labels,datasets},options})}
function miOpenMetric(id){const m=miData.metrics.find(m=>m.id===id);if(!m)return;gbOpenDialog(m.label,'MARKET MEASURE · '+m.period,`<div class="mi-metric-reader"><strong>${esc(miFormat(m))}</strong><div class="mi-reader-measures">${[['Period',m.period],['Geography',m.geography],['Evidence class',m.basis],['Published',m.publishedAt]].map(([k,v])=>`<article><small>${esc(k)}</small><b>${esc(v||'Source date retained')}</b></article>`).join('')}</div><h3>Definition</h3><p>${esc(m.definition)}</p>${m.caveats?.length?'<h3>Read before comparing</h3><ul>'+m.caveats.map(c=>'<li>'+esc(c)+'</li>').join('')+'</ul>':''}<h3>GoTo decision context</h3><p>${esc(m.gotoImplication)}</p>${m.series?.length?'<h3>Published observations</h3><table class="ux-table"><thead><tr><th>Period</th><th>Value</th><th>Evidence</th></tr></thead><tbody>'+m.series.map(x=>'<tr><td>'+esc(x.period)+'</td><td>'+esc(miFormat({...m,value:x.value}))+'</td><td>'+miSource(x.sourceUrl||m.sourceUrl,'Period source')+'</td></tr>').join('')+'</tbody></table>':''}<h3>Original evidence</h3><p>${esc(m.sourceNote)}</p>${miSource(m.sourceUrl,m.sourceName)}<div>${miButton('Preview original in dashboard','preview',m.sourceUrl)}</div><div id="miSourcePreview"></div></div>`)}
function miPerformance(){const rows=miData.companyMetrics,brands=[...new Set(rows.map(m=>m.businessEntityId||m.entityId))];return `<div class="mi-performance-intro"><span class="ux-eyebrow">ISSUER-REPORTED PERFORMANCE</span><h3>Compare the metric, period and geography.</h3><p>Company-wide revenue, platform volume and lending balances have different scopes. These figures do not establish Indonesia market share.</p></div><div class="mi-performance-grid">${brands.map(id=>{const rs=rows.filter(m=>(m.businessEntityId||m.entityId)===id);return `<article class="mi-performance-company"><header>${miLogo(id)}<div><h3>${esc(rs[0].company||miName(id))}</h3><span>${esc(rs[0].period)} · ${esc(rs[0].geography)}</span></div></header>${rs.map(m=>`<button class="mi-performance-measure" data-mi-action="performance-detail" data-mi-key="${esc(m.id)}"><span>${esc(m.label||m.metric)}</span><strong>${esc(miFormat(m))}</strong>${m.yoyPct!=null?`<em>${m.yoyPct>=0?'+':''}${m.yoyPct}% YoY</em>`:''}<small>${esc(m.geography)}</small></button>`).join('')}${miSource(rs[0].sourceUrl,rs[0].sourceName)}</article>`}).join('')}</div><div class="mi-chart-card"><div class="mi-chart-heading"><h4>Reported loan-book growth</h4><span>Year on year · scopes differ</span></div><div class="mi-chart-area" id="miPerformanceChartArea"><canvas id="miRevenueGrowth" aria-label="Issuer-reported loan-book growth" role="img"></canvas></div><p class="mi-chart-caption">Each lender is compared with its own prior year. Grab’s portfolio includes Superbank consolidation from June. Country coverage, on/off-book scope and accounting differ; these percentages do not establish Indonesia market share or organic growth.</p></div>`}
function miPaintPerformance(){const rs=miData.companyMetrics.filter(m=>/loan.*(?:outstanding|portfolio)/i.test(m.metric)&&m.yoyPct!=null),ids=new Set(),rows=rs.filter(m=>{if(ids.has(m.entityId))return false;ids.add(m.entityId);return true});if(!rows.length){$('#miPerformanceChartArea')?.remove();return}miChart('miRevenueGrowth','bar',rows.map(m=>m.company||miName(m.entityId)),[{label:'Loan-book growth YoY',data:rows.map(m=>m.yoyPct),backgroundColor:miColors,borderRadius:6,maxBarThickness:75}],{suffix:'%'})}
function miOpenPerformance(id){const m=miData.companyMetrics.find(m=>m.id===id);if(!m)return;gbOpenDialog(m.company+' · '+(m.label||m.metric),'ISSUER REPORTED · '+m.period,`<div class="mi-metric-reader"><div class="mi-inline-brand">${miLogo(m.entityId)}<strong>${esc(miFormat(m))}</strong></div><div class="mi-reader-measures"><article><small>REPORTING PERIOD</small><b>${esc(m.period)}</b></article><article><small>GEOGRAPHIC SCOPE</small><b>${esc(m.geography)}</b></article></div><h3>Definition & comparison scope</h3><p>${esc(m.definition)}</p><p>${esc(m.comparabilityNote)}</p>${miSource(m.sourceUrl,m.sourceName)}<div>${miButton('Preview source in dashboard','preview',m.sourceUrl)}</div><div id="miSourcePreview"></div></div>`)}
const miOriginalBrief=R.brief;R.brief=function(){miOriginalBrief();miBriefPanel()};
function miBriefPanel(){const root=$('#v-brief'),meta=D.marketIntelligenceMeta;if(!root||!meta||root.querySelector('.mi-brief-panel'))return;const food=meta.featured.find(m=>m.sectorId==='food'),ecom=meta.featured.find(m=>m.sectorId==='ecommerce'),cards=meta.featured.slice(0,4);const html=`<section class="mi-brief-panel"><div class="mi-section-title"><div><span class="ux-eyebrow">COMPETITIVE MARKET CONTEXT</span><h3>The markets behind the moves</h3></div><a class="btn" href="?marketView=markets#competitors">Open market intelligence →</a></div><div class="mi-brief-grid">${food?.shares?.length?`<article class="mi-brief-share"><header><div><small>INDONESIA FOOD DELIVERY · ${esc(food.period)}</small><strong>${esc(miFormat(food))}</strong></div><span>GMV estimate</span></header><div class="mi-stacked-share" aria-label="Food delivery GMV shares">${food.shares.map((s,i)=>`<span style="width:${s.sharePct}%;background:${miColors[i]}" title="${esc(s.name+': '+s.sharePct+'%')}">${s.sharePct}%</span>`).join('')}</div><div class="mi-share-key">${food.shares.map((s,i)=>`<span><i style="background:${miColors[i]}"></i>${esc(s.name)}</span>`).join('')}</div><a href="?marketView=markets#competitors">See the historical shift →</a></article>`:''}<article class="mi-brief-network"><div><span class="ux-eyebrow">COMMERCIAL INTERDEPENDENCIES</span><h4>Competitors can also be partners.</h4></div><div class="mi-brief-network-icons">${['goto','shopee','grab','tokopedia'].map(id=>logo(id,byId[id]?.name||id,1)).join('<span>↔</span>')}</div><div class="mi-brief-network-counts"><b>${meta.counts.relationships}<small>sourced relationships</small></b><b>${meta.counts.sharedProviders}<small>shared providers</small></b></div><a href="?marketView=ecosystem#competitors">Explore the connected ecosystem →</a></article></div><div class="mi-brief-metrics">${cards.filter(m=>m!==food).slice(0,3).map(m=>`<a href="?marketView=markets&marketMode=${m.shares?.length?'shares':'scale'}&marketMetric=${esc(m.id)}#competitors"><small>${esc(m.label)} · ${esc(m.period)}</small><b>${esc(miFormat(m))}</b><span>${esc(m.basis)}</span></a>`).join('')}</div></section>`;const anchor=root.querySelector('.gb-brief-trends');if(anchor)anchor.insertAdjacentHTML('afterend',html);else root.insertAdjacentHTML('afterbegin',html)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-mi-action]');if(!b)return;const a=b.dataset.miAction,k=b.dataset.miKey;if(a==='view'){miState.view=k;miState.page=1;const u=new URL(location.href);u.searchParams.set('marketView',k);history.replaceState(null,'',u.pathname+u.search+u.hash);renderCompetition();return}if(a==='retry'){renderCompetition();return}try{await miLoad();if(a==='platform'){miState.platform=k;miState.selected=null;miState.zoom=1;miState.page=1;miRender()}if(a==='segment'){if(['ods','finance'].includes(k)){ciState.segment=k;ciState.allServices=true;ciState.service=CI.services.find(s=>s.segment===k).id}miState.segment=k;miState.service='all';miState.metric=null;miState.marketsector='all';miState.selected=null;miState.page=1;miRender()}if(a==='layout'){if(k==='events'){miState.query='';miState.service='all';miState.relation='all';miState.segment='all';miState.eventPage=1}if(k==='flow'&&miState.platform==='all')miState.platform='shopee';if(k==='network'&&['matrix','providers'].includes(miState.layout)&&miState.platform==='all')miState.platform='goto';miState.layout=k;const u=new URL(location.href);u.searchParams.set('marketLayout',k);history.replaceState(null,'',u.pathname+u.search+u.hash);if(['matrix','providers'].includes(k))miState.platform='all';miState.page=1;miRender()}if(a==='reset'){Object.assign(miState,{platform:'goto',segment:'all',service:'all',relation:'all',query:'',selected:null,zoom:1,page:1});miRender()}if(a==='heat-cell')miOpenHeatCell(k);if(a==='provider-cell')miOpenHeatCell(k,true);if(a==='provider-network'){const[p,id]=k.split('|');miState.platform=p;miState.query=miName(id);miState.layout='network';miState.zoom=1;if(gbDialog().open)gbDialog().close();miRender()}if(a==='matrix-cell'){if(gbDialog().open)gbDialog().close();const[p,s]=k.split('|');miState.platform=p;miState.service=s;miState.layout='network';miState.zoom=1;miState.selected=null;miRender()}if(a==='page'){miState.page=Number(k);miRender()}if(a==='metric'){miState.metric=k;miRender()}if(a==='node-details')miOpenNode(k);if(a==='inspect-edge')miInspectEdge(k);if(a==='node-table'){miState.platform='all';miState.query=miName(k);miState.layout='table';miState.page=1;if(gbDialog().open)gbDialog().close();miRender()}if(a==='entity-workspace'){if(gbDialog().open)gbDialog().close();openEntity(k)}if(a==='relationship')miOpenRelationship(k);if(a==='metric-detail')miOpenMetric(k);if(a==='performance-detail')miOpenPerformance(k);if(a==='preview'){const u=uxSafeUrl(k),target=$('#miSourcePreview');if(u&&target)target.innerHTML=`<iframe title="Original source preview" src="${esc(u)}" loading="lazy" referrerpolicy="no-referrer"></iframe><p class="gb-small">Some publishers restrict embedded previews. The sourced facts and original link remain above.</p>`}if(['zoom-in','zoom-out','fit'].includes(a)){const stage=$('#miGraphStage'),vp=$('#miGraphViewport');if(stage&&vp){miState.zoom=a==='fit'?(vp.clientWidth<600?1:Math.max(.8,Math.min(1,(vp.clientWidth-20)/830))):Math.max(.4,Math.min(1.7,miState.zoom+(a==='zoom-in'?.15:-.15)));stage.style.zoom=miState.zoom}}}catch(error){b.textContent='Could not load · retry'}});

function miInspectEdge(id){const r=miData.relationships.find(r=>r.id===id);if(!r)return;miState.selected=id;const panel=$('#miInspector');if(panel)panel.innerHTML=miInspector(r);document.querySelectorAll('#miGraphViewport .mi-edge').forEach(el=>el.classList.toggle('selected',el.dataset.miEdge===id));document.querySelectorAll('#miGraphViewport .mi-node').forEach(el=>el.classList.toggle('connected',[r.fromId,r.toId].includes(el.dataset.miNode)))}
function miNodePanel(id){const p=miEntity(id),rows=miData.relationships.filter(r=>r.fromId===id||r.toId===id),platforms=[...new Set(rows.map(r=>r.platformId))];return `<div class="mi-node-summary"><span class="ux-eyebrow">COMPANY CONNECTIONS</span><div class="mi-node-brand">${miLogo(id)}<div><h3>${esc(p.name)}</h3><span>${esc(p.kind==='platform'?'Platform ecosystem':p.kind==='service'?'Operating service':p.kind==='affiliate'?'Affiliate / partner':'External provider')}</span></div></div><div class="mi-node-counts"><b>${rows.length}<small>documented links</small></b><b>${platforms.length}<small>ecosystems connected</small></b></div></div><h4 class="mi-node-connection-title">Connected businesses</h4><div class="mi-node-connections">${rows.slice(0,7).map(r=>{const other=r.fromId===id?r.toId:r.fromId;return miButton(miLogo(other)+`<span><b>${esc(miName(other))}</b><small>${esc(r.relationType)}</small></span><i>→</i>`,'inspect-edge',r.id,'mi-node-connection')}).join('')}</div>${rows.length>7?`<p class="gb-small">${rows.length-7} more connections in full details</p>`:''}<div class="mi-node-panel-actions">${miButton('Company & all connections →','node-details',id)}${miSource(p.website,'Company website')}</div>`}
function miInspectNode(id){const p=miEntity(id);if(!p)return;const panel=$('#miInspector');if(panel)panel.innerHTML=miNodePanel(id);const rows=miScopeRelationships().filter(r=>r.fromId===id||r.toId===id),related=new Set(rows.flatMap(r=>[r.fromId,r.toId])),edgeIds=new Set(rows.map(r=>r.id));document.querySelectorAll('#miGraphViewport .mi-edge').forEach(e=>e.classList.toggle('selected',edgeIds.has(e.dataset.miEdge)));document.querySelectorAll('#miGraphViewport .mi-node').forEach(e=>{const selected=related.has(e.dataset.miNode);e.classList.toggle('connected',selected);e.setAttribute('aria-pressed',String(selected))})}
function miOpenNode(id){const p=miEntity(id);if(!p)return;const rows=miData.relationships.filter(r=>r.fromId===id||r.toId===id);const original=miState.page;miState.page=1;const table=miRelationshipTable(rows).replace(/<div class="db-pagination">[\s\S]*$/,'');miState.page=original;gbOpenDialog(p.name,'COMPANY & COMMERCIAL CONNECTIONS',`<div class="mi-company-reader"><div class="mi-node-brand">${miLogo(id)}<div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p></div></div><div class="mi-node-panel-actions">${miSource(p.website,'Company website')}${byId[id]?miButton('Open full company workspace','entity-workspace',id):''}</div><h3>${rows.length} sourced connections</h3>${table}${rows.length>20?'<p class="gb-small">First 20 connections shown.</p>':''}${miButton('Explore all connections in the table →','node-table',id)}</div>`)}

/* Market share is always a sourced percentage with a named denominator. */
const msPct=v=>Number(v).toLocaleString('en-US',{maximumFractionDigits:1})+'%';
const msPP=v=>(v>0?'+':'')+Number(v).toLocaleString('en-US',{maximumFractionDigits:1})+' pp';
const msIsSurvey=m=>m.shareKind==='survey_usage';
const msSector=m=>m.shareSectorLabel||({ride:'Passenger ride-hailing',ecommerce:'E-commerce',food:'Food delivery'}[m.sectorId])||miData.services.find(s=>s.id===m.sectorId)?.title||m.label;
function msSnapshots(m){const snapshots=((miState.shareGrouping==='aligned'&&m.comparisonShareSeries?.length?m.comparisonShareSeries:m.shareSeries)||[]).map(s=>({...s,sourceUrl:s.sourceUrl||m.sourceUrl,publishedAt:s.publishedAt||m.publishedAt}));if(!snapshots.some(s=>s.period===m.period))snapshots.push({period:m.period,shares:m.shares,sourceUrl:m.sourceUrl,publishedAt:m.publishedAt});return snapshots.sort((a,b)=>a.period.localeCompare(b.period,undefined,{numeric:true}))}
function msShareMetrics(){return miMetricList().filter(m=>m.shares?.length)}
function msSelected(){const rows=msShareMetrics();if(!rows.some(m=>m.id===miState.shareMetric))miState.shareMetric=rows.find(m=>!msIsSurvey(m)&&m.sectorId==='food')?.id||rows[0]?.id;return rows.find(m=>m.id===miState.shareMetric)}
function msGroup(id){return {gofood:'goto',gojek:'goto',gocar:'goto',gojek_ods:'goto',shopeefood:'shopee',grabfood:'grab',tiktok_tokopedia:'tiktok_tokopedia'}[id]||id}
function msLogo(id){return miLogo({tiktok_tokopedia:'tokopedia',gofood:'gofood',gojek:'gojek'}[id]||id)}
function msShareChange(m,entityId){const ss=msSnapshots(m);if(ss.length<2)return null;const latest=ss[ss.length-1],prior=ss[ss.length-2],now=latest.shares.find(x=>x.entityId===entityId),before=prior.shares.find(x=>x.entityId===entityId);if(!now||!before||latest.comparableToPrior===false||m.shareTrendComparable===false)return null;return {value:Number((now.sharePct-before.sharePct).toFixed(2)),from:prior.period,to:latest.period}}
function msShade(pct){return pct===0?0:pct<=10?1:pct<=25?2:pct<=40?3:pct<=60?4:5}
function msShareButton(m,s,period){return `<button class="ms-share-cell ms-share-${msShade(s.sharePct)}" data-mi-action="share-evidence" data-mi-key="${esc(m.id+'|'+period+'|'+s.entityId)}" title="${esc(s.name+' · '+period+' · '+msPct(s.sharePct))}"><strong>${msPct(s.sharePct)}</strong>${s.derived?'<small class="ms-derived">Calculated sum</small>':s.cellLabel?'<small>'+esc(s.cellLabel)+'</small>':''}</button>`}
function msLegend(survey=false){return `<div class="ms-color-key"><b>${survey?'Survey respondents':'Published share'}</b>${[[0,'0%'],[1,'≤10%'],[2,'≤25%'],[3,'≤40%'],[4,'≤60%'],[5,'>60%']].map(([i,t])=>`<span><i class="ms-share-${i}"></i>${t}</span>`).join('')}<em>— Not reported</em></div>`}
function msModeNav(){return `<div class="ms-mode-tabs" role="group" aria-label="Market intelligence view">${[['shares','Market-share heatmaps'],['scale','Market size & adoption'],['surveys','Wallet survey insights'],['evidence','Source table']].map(([k,v])=>miButton(v,'market-mode',k,'ms-mode '+(miState.marketMode===k?'on':''))).join('')}</div>`}
function miMarkets(){return `${msModeNav()}<div class="ms-market-tools"><div class="mi-market-segment">${[['all','All markets'],['ods','ODS & commerce'],['finance','Financial services']].map(([k,v])=>`<button data-mi-action="segment" data-mi-key="${k}" aria-pressed="${miState.segment===k}">${v}</button>`).join('')}</div>${miState.marketMode==='scale'||miState.marketMode==='evidence'?miField('miFilterMarketsector','Market sector',[['all','All sectors'],...[...new Set(miData.metrics.map(m=>m.sectorId))].map(id=>[id,miData.services.find(s=>s.id===id)?.title||'Commerce'])],miState.marketsector):''}</div>${miState.marketMode==='scale'?msScaleView():miState.marketMode==='evidence'?msEvidenceView():miState.marketMode==='surveys'?msSurveyView():msShareView()}`}
function msShareView(){const metrics=msShareMetrics(),m=msSelected();return `<div class="ms-share-title"><div><span class="ux-eyebrow">INDONESIA · COMPETITIVE POSITION</span><h3>Who has share. Who is gaining.</h3><p>Percentages retain their published market, period and measurement basis.</p></div><div class="ms-view-toggle" role="group" aria-label="Share comparison layout">${[['history','Share over time'],['snapshot','Market snapshots']].map(([k,v])=>miButton(v,'share-view',k,'ms-view '+(miState.shareView===k?'on':''))).join('')}</div></div>${!metrics.length?msShareGap():miState.shareView==='snapshot'?msSnapshotView(metrics):`<div class="ms-sector-rail">${metrics.map(x=>miButton(`<span>${msIsSurvey(x)?'SURVEY USAGE':x.period}</span><b>${esc(msSector(x))}</b><small>${esc(x.shareBasisLabel||'GMV share')}</small>`,'share-metric',x.id,'ms-sector '+(m?.id===x.id?'on':''))).join('')}</div>${m?msShareDetail(m):''}`}`}
function msShareGap(){const finance=miState.segment==='finance';return `<section class="ms-data-boundary"><span class="ux-eyebrow">${finance?'FINANCIAL SERVICES':'MARKET COVERAGE'}</span><h4>A total market is not a platform-share estimate.</h4><p>Public sources in this registry do not provide a comparable provider-by-provider transaction-share series for this selection. Industry payment volume, lending balances and survey usage have different denominators.</p><div>${miButton('Read wallet survey comparisons →','market-mode','surveys')}${miButton('Explore official industry measures →','market-mode','scale')}${miButton('Compare issuer performance →','view','performance')}</div></section>`}
function msShareDetail(m){const snapshots=msSnapshots(m),latest=snapshots[snapshots.length-1],sorted=[...latest.shares].sort((a,b)=>b.sharePct-a.sharePct),leader=sorted[0],changes=sorted.map(s=>({s,c:msShareChange(m,s.entityId)})).filter(x=>x.c),gain=changes.sort((a,b)=>b.c.value-a.c.value)[0],total=latest.shares.reduce((n,s)=>n+s.sharePct,0);return `<section class="ms-share-detail"><div class="ms-context-strip"><div><small>${msIsSurvey(m)?'SURVEY MEASURE':'MARKET DEFINITION'}</small><b>${esc(m.shareDefinition||m.metric)}</b><span>${esc(m.geography)} · ${esc(latest.period)} · ${esc(m.basis)}</span></div>${miButton('Methodology & source','metric-detail',m.id)}</div><div class="ms-insight-row"><article><small>LEADING ${msIsSurvey(m)?'REPORTED BRAND':'PLATFORM'}</small><div>${msLogo(leader.entityId)}<strong>${msPct(leader.sharePct)}</strong></div><b>${esc(leader.name)}</b></article>${gain?`<article><small>LARGEST SHARE GAIN</small><div>${msLogo(gain.s.entityId)}<strong class="${gain.c.value>0?'ms-up':''}">${msPP(gain.c.value)}</strong></div><b>${esc(gain.s.name)} · ${esc(gain.c.from)} → ${esc(gain.c.to)}</b></article>`:`<article><small>REPORTING WINDOW</small><div><strong>${esc(latest.period)}</strong></div><b>Published ${esc(latest.publishedAt||m.publishedAt||'date retained')}</b></article>`}<article><small>${msIsSurvey(m)?'SAMPLE & METHOD':'REPORTED COVERAGE'}</small><div><strong>${msIsSurvey(m)?(m.sampleSize?'n='+Number(m.sampleSize).toLocaleString('en-US'):'Survey'):total.toLocaleString('en-US',{maximumFractionDigits:1})+'%'}</strong></div><b>${msIsSurvey(m)?(m.multipleResponse?'Multiple responses permitted':'Source survey population'):Math.abs(total-100)<.01?'Full published split':total>100?'Rounded shares; retained as published':'Partial published split; remainder not allocated'}</b></article></div><article class="ms-heat-card"><div class="ms-card-head"><div><span class="ux-eyebrow">${msIsSurvey(m)?'REPORTED RESPONDENT USAGE':'MARKET-SHARE HEATMAP'}</span><h4>${esc(m.label)}</h4></div><span>Cell = ${msIsSurvey(m)?'% of defined respondents':'% of defined market'}</span></div>${m.comparisonShareSeries?.length?'<div class="ms-grouping-control"><span>Historical grouping</span><div class="ms-view-toggle">'+[['original','As published'],['aligned','Combine TikTok + Tokopedia']].map(([k,v])=>miButton(v,'share-grouping',k,'ms-view '+((miState.shareGrouping||'original')===k?'on':''))).join('')+'</div></div>':''}${miState.shareGrouping==='aligned'&&m.comparisonShareSeries?.length?'<p class="ms-grouping-note">Earlier TikTok Shop + Tokopedia cells are calculated sums of separately published shares, not a claim that they were one company or operator.</p>':''}${msLegend(msIsSurvey(m))}${msHistoryTable(m,snapshots)}<p class="ms-chart-foot">${esc(m.shareNote||m.caveats?.find(c=>/shares refer|shares.*total|rounded.*shares|combined|partial split|survey responses/i.test(c))||'Missing shares stay blank. Select a percentage for its source and definition.')}</p></article>${msChartCard(m,snapshots)}<div class="ms-source-strip">${miSource(m.sourceUrl,m.sourceName)}<span>${esc(m.publishedAt||'')} · reporting period ${esc(m.period)}</span>${miButton('Read all caveats','metric-detail',m.id,'mi-detail-link')}</div><div class="ms-decision-note"><span class="ux-eyebrow">GOTO LENS · ANALYST INTERPRETATION</span><p>${esc(m.gotoImplication)}</p></div></section>`}
function msHistoryTable(m,snapshots){const keys=[...new Map(snapshots.flatMap(s=>s.shares).map(s=>[s.entityId,s])).values()].sort((a,b)=>{const latest=snapshots[snapshots.length-1];return (latest.shares.find(s=>s.entityId===b.entityId)?.sharePct??-1)-(latest.shares.find(s=>s.entityId===a.entityId)?.sharePct??-1)});return `<div class="ms-heat-scroll"><table class="ms-share-table"><thead><tr><th>Company / published grouping</th>${snapshots.map(s=>`<th>${esc(s.period)}<small>${esc(m.sharePeriodLabel||'Published estimate')}</small></th>`).join('')}<th>Latest change<small>percentage points</small></th></tr></thead><tbody>${keys.map(s=>{const delta=msShareChange(m,s.entityId);return `<tr><th><div>${msLogo(s.entityId)}<span>${esc(s.name)}</span></div></th>${snapshots.map(p=>{const value=p.shares.find(x=>x.entityId===s.entityId);return `<td>${value?msShareButton(m,value,p.period):'<span class="ms-missing" title="Not separately reported for this period">—</span>'}</td>`}).join('')}<td>${delta?`<span class="ms-change ${delta.value>0?'ms-up':delta.value<0?'ms-down':''}">${msPP(delta.value)}</span><small>${esc(delta.from)} → ${esc(delta.to)}</small>`:'<span class="ms-missing">—</span>'}</td></tr>`}).join('')}</tbody></table></div>`}
function msSnapshotView(metrics){const shares=metrics.filter(m=>!msIsSurvey(m)),surveys=metrics.filter(msIsSurvey);if(!shares.length)return `<div class="ms-data-boundary"><h4>Survey use is separate from transaction market share.</h4><p>No comparable transaction-share split is published in the sources reviewed for this segment. Available consumer survey measures are accessible under Share over time.</p>${miButton('See survey evidence →','share-view','history')}${miButton('Official industry scale →','market-mode','scale')}</div>`;const keys=[...new Set(shares.flatMap(m=>m.shares.map(s=>msGroup(s.entityId))))];return `<div class="ms-context-strip"><div><small>SEPARATE MARKET DENOMINATORS</small><b>Latest published snapshots</b><span>Each column is a different market and reporting period. Do not add shares across columns.</span></div></div><article class="ms-heat-card">${msLegend()}<div class="ms-heat-scroll"><table class="ms-share-table ms-snapshot-table"><thead><tr><th>Platform / research grouping</th>${shares.map(m=>`<th>${esc(msSector(m))}<small>${esc(m.period)} · ${esc(m.shareBasisLabel||'GMV share')}</small></th>`).join('')}</tr></thead><tbody>${keys.map(id=>`<tr><th><div>${msLogo(id)}<span>${esc(id==='tiktok_tokopedia'?'TikTok Shop + Tokopedia':id==='goto'?'Gojek / GoTo':miName(id))}</span></div></th>${shares.map(m=>{const s=m.shares.find(x=>msGroup(x.entityId)===id);return `<td>${s?msShareButton(m,{...s,cellLabel:s.name},m.period):'<span class="ms-missing" title="No separately reported share in this market">—</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="ms-chart-foot">Rounded percentages and partial splits are preserved. A blank cell is not zero. ${surveys.length?'Consumer surveys are excluded from this market-share comparison.':''}</p></article><div class="ms-snapshot-sources">${shares.map(m=>`<article><b>${esc(msSector(m))} · ${esc(m.period)}</b><p>${esc(m.shareDefinition||m.definition)}</p>${miSource(m.sourceUrl,m.sourceName)}</article>`).join('')}</div>`}
function msChartCard(m,ss){const history=ss.length>1&&m.shareTrendComparable!==false,first=miState.shareChart==='change'&&ss.length>1?ss[ss.length-2]:ss[0];return `<article class="mi-chart-card ms-share-chart"><div class="mi-chart-heading"><div><h4>${history?(miState.shareChart==='change'?'Who gained and lost share':'How positions changed'):'Published competitive positions'}</h4><span>${history?esc(first.period)+' → '+esc(ss[ss.length-1].period):esc(m.period)} · ${msIsSurvey(m)?'survey respondents':'defined market'}</span></div>${history?`<div class="ms-view-toggle">${[['trend','Share trend'],['change','Change in pp']].map(([k,v])=>miButton(v,'share-chart',k,'ms-view '+(miState.shareChart===k?'on':''))).join('')}</div>`:''}</div><div class="mi-chart-area"><canvas id="msShareTrend" role="img" aria-label="${history?'Published share history and changes':'Published share comparison'}"></canvas></div><p class="ms-chart-foot">${history?'Changes are percentage-point differences between published observations, not percentage growth.':'One published snapshot is available. No trend has been interpolated.'}</p></article>`}
function msOpenShareEvidence(key){const[id,period,entity]=key.split('|'),m=miData.metrics.find(m=>m.id===id);if(!m)return;const observation=msSnapshots(m).find(s=>s.period===period),s=observation?.shares.find(s=>s.entityId===entity);if(!s)return;gbOpenDialog(s.name+' · '+msPct(s.sharePct),msIsSurvey(m)?'SURVEY RESPONDENT USAGE':'PUBLISHED MARKET SHARE',`<div class="mi-metric-reader ms-share-reader"><div class="mi-inline-brand">${msLogo(s.entityId)}<strong>${msPct(s.sharePct)}</strong></div><div class="mi-reader-measures">${[['Reporting period',period],['Defined market',m.shareDefinition||m.metric],['Geography',m.geography],['Evidence class',m.basis],['Published',observation.publishedAt||m.publishedAt],['Grouping',s.name]].map(([k,v])=>`<article><small>${esc(k)}</small><b>${esc(v||'Source date retained')}</b></article>`).join('')}</div><p>${esc(m.definition)}</p>${observation.note?'<p class="ms-grouping-note">Source context: '+esc(observation.note)+'</p>':''}${s.derived?'<div class="ms-grouping-note"><b>Calculated historical grouping: '+esc(s.calculation)+'</b><p>'+esc(s.basis)+'</p></div>':''}${m.caveats?.length?'<h3>Interpretation limits</h3><ul>'+m.caveats.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':''}${miSource(observation.sourceUrl,observation.sourceName||m.sourceName)}<div>${miButton('Read complete market methodology','metric-detail',m.id)}</div></div>`)}
function msScaleView(){const metrics=miMetricList().filter(m=>!msIsSurvey(m)&&!(m.shares?.length&&!m.currency&&/share/i.test(m.unit)));if(!metrics.some(m=>m.id===miState.metric))miState.metric=metrics.find(m=>m.id===miState.shareMetric)?.id||metrics[0]?.id;const m=metrics.find(m=>m.id===miState.metric);return `<div class="ms-scale-intro"><h3>Market scale, without confusing the units.</h3><p>Transaction flows, GMV, user counts and outstanding credit remain separate measures.</p></div><div class="mi-metric-grid">${metrics.map(x=>miButton(`<span>${esc(x.label)}</span><strong>${esc(miFormat(x))}</strong><small>${esc(x.period)} · ${esc(x.geography)}</small><em>${x.yoyPct!=null?(x.yoyPct>=0?'+':'')+x.yoyPct+'% YoY':esc(x.basis)}</em>`,'metric',x.id,'mi-metric-card '+(m?.id===x.id?'selected':''))).join('')}</div>${m?msScaleDetail(m):'<p>No sourced measure matches.</p>'}`}
function msScaleDetail(m){const comparable=m.series?.length>1&&m.trendComparable!==false,observations=m.series?.length>1;return `<section class="ms-scale-detail"><div class="ms-scale-fact"><div><span class="ux-eyebrow">${esc(m.basis)} · ${esc(m.period)}</span><h3>${esc(m.label)}</h3><div class="ms-scale-value"><strong>${esc(miFormat(m))}</strong>${m.yoyPct!=null?'<span>'+(m.yoyPct>0?'+':'')+m.yoyPct+'% YoY</span>':''}</div><p>${esc(m.definition)}</p></div><div class="ms-scale-source">${miButton('Definitions & evidence','metric-detail',m.id)}${miSource(m.sourceUrl,m.sourceName)}<small>Published ${esc(m.publishedAt||'date retained')}</small></div></div>${comparable?`<article class="mi-chart-card"><div class="mi-chart-heading"><h4>Published observations</h4><span>${esc(m.currency||'')} ${esc(m.unit)}</span></div><div class="mi-chart-area"><canvas id="miMarketTrend" role="img" aria-label="Published market observations"></canvas></div></article>`:observations?`<div class="ms-observed-periods"><div><h4>Reported observations</h4><p>${esc(m.caveats?.find(c=>/scope|footnote/i.test(c))||'Source definitions differ between periods; these observations are not connected as a trend.')}</p></div><div>${m.series.map(s=>`<article><small>${esc(s.period)}</small><b>${esc(miFormat({...m,value:s.value}))}</b>${miSource(s.sourceUrl||m.sourceUrl,'Period source')}</article>`).join('')}</div></div>`:''}<div class="ms-decision-note"><span class="ux-eyebrow">GOTO LENS · ANALYST INTERPRETATION</span><p>${esc(m.gotoImplication)}</p></div></section>`}
function msEvidenceView(){const metrics=miMetricList();return `<div class="ms-scale-intro"><h3>${metrics.length} market measures and their definitions</h3><p>Select a measure to inspect reporting dates, caveats and its original source.</p></div><div class="ux-table-wrap"><table class="ux-table ms-evidence-table"><thead><tr><th>Measure</th><th>Reported value</th><th>Period</th><th>Basis & scope</th><th>Source</th></tr></thead><tbody>${metrics.map(m=>`<tr><td>${miButton(esc(m.label),'metric-detail',m.id,'ux-title-button')}</td><td><b>${esc(miFormat(m))}</b></td><td>${esc(m.period)}</td><td>${esc(m.basis)}<small>${esc(m.definition)}</small></td><td>${miSource(m.sourceUrl,m.sourceName)}<small>Published ${esc(m.publishedAt||'date retained')}</small></td></tr>`).join('')}</tbody></table></div>`}
function miPaintMarkets(){if(miState.marketMode==='surveys'){msPaintSurvey();return}if(miState.marketMode==='evidence'||miState.marketMode==='shares'&&miState.shareView==='snapshot')return;if(miState.marketMode==='scale'){const m=miData.metrics.find(m=>m.id===miState.metric);if(m?.series?.length>1&&m.trendComparable!==false)miChart('miMarketTrend','bar',m.series.map(x=>x.period),[{label:m.currency?m.currency+' '+m.unit:m.unit,data:m.series.map(x=>x.value),backgroundColor:'#20b889',borderRadius:5,maxBarThickness:68}]);return}const m=msSelected();if(!m)return;const ss=msSnapshots(m),last=ss[ss.length-1],history=ss.length>1&&m.shareTrendComparable!==false,keys=[...new Map(ss.flatMap(x=>x.shares).map(x=>[x.entityId,x])).values()];if(history&&miState.shareChart==='trend')miChart('msShareTrend','line',ss.map(s=>s.period),keys.map((s,i)=>({label:s.name,data:ss.map(p=>p.shares.find(x=>x.entityId===s.entityId)?.sharePct??null),borderColor:miColors[i%miColors.length],backgroundColor:miColors[i%miColors.length],pointRadius:5,borderWidth:3,tension:0,spanGaps:false})),{suffix:'%',options:{scales:{y:{min:0,max:100}}}});else if(history){const rows=keys.map(s=>({s,c:msShareChange(m,s.entityId)})).filter(x=>x.c);miChart('msShareTrend','bar',rows.map(x=>x.s.name),[{label:'Latest share change (pp)',data:rows.map(x=>x.c.value),backgroundColor:rows.map(x=>x.c.value>=0?'#20b889':'#dd746e'),borderRadius:5,maxBarThickness:35}],{suffix:' pp',options:{indexAxis:'y'}})}else miChart('msShareTrend','bar',last.shares.map(x=>x.name),[{label:msIsSurvey(m)?'Survey respondents':'Market share',data:last.shares.map(x=>x.sharePct),backgroundColor:miColors,borderRadius:5,maxBarThickness:36}],{suffix:'%',options:{indexAxis:'y',scales:{x:{min:0,max:100}}}})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-mi-action]');if(!b)return;const a=b.dataset.miAction,k=b.dataset.miKey;if(a==='market-mode'){miState.marketMode=k;if(k==='shares')miState.marketsector='all';const u=new URL(location.href);u.searchParams.set('marketMode',k);history.replaceState(null,'',u.pathname+u.search+u.hash);miRender()}if(a==='share-metric'){miState.shareMetric=k;miState.metric=k;miState.shareChart='trend';const u=new URL(location.href);u.searchParams.set('marketMetric',k);history.replaceState(null,'',u.pathname+u.search+u.hash);miRender()}if(a==='share-view'){miState.shareView=k;miRender()}if(a==='share-grouping'){miState.shareGrouping=k;miRender()}if(a==='share-chart'){miState.shareChart=k;miRender()}if(a==='share-evidence')msOpenShareEvidence(k)});
function msSurveyCurrent(){const rows=miData.surveys||[];return rows.find(s=>s.id===miState.surveyMetric)||rows.find(s=>s.id==='id-wallet-p3m-ipsos-202601')||rows[0]}
function msSurveyMatrix(s){const observations=s.observations||[],hasBrands=observations.some(o=>o.entityId),hasCategories=hasBrands&&observations.some(o=>o.categoryId),columns=hasCategories?[...new Map(observations.map(o=>[o.categoryId,{id:o.categoryId,name:o.category}])).values()]:[{id:'measure',name:s.metric}],rows=[...new Map(observations.map(o=>[hasBrands?o.entityId:o.categoryId,{id:hasBrands?o.entityId:o.categoryId,name:hasBrands?o.company:o.category}])).values()];return {observations,hasBrands,hasCategories,columns,rows}}
function msSurveyView(){const surveys=miData.surveys||[],s=msSurveyCurrent();if(!s)return '<div class="ms-data-boundary"><h4>No sourced survey comparison available</h4><p>Official industry measures remain available under Market size & adoption.</p></div>';const matrix=msSurveyMatrix(s);return `<div class="ms-share-title"><div><span class="ux-eyebrow">FINANCIAL SERVICES · CONSUMER EVIDENCE</span><h3>Wallet use and payment preferences</h3><p>These are survey responses. They do not measure transaction-value or transaction-count market share.</p></div></div><div class="ms-sector-rail">${surveys.map(x=>miButton(`<span>${esc(x.sourceName)}</span><b>${esc(x.metric)}</b><small>${esc(x.period)}</small>`,'survey-study',x.id,'ms-sector '+(x.id===s.id?'on':''))).join('')}</div><div class="ms-survey-boundary"><b>SURVEY EVIDENCE · NOT TRANSACTION MARKET SHARE</b><span>${s.multipleResponse?'Multiple responses permitted. Totals may exceed 100%.':'Retain the source’s response population and question wording.'}</span></div><div class="ms-context-strip"><div><small>${esc(s.sourceName)} · ${esc(s.geography)}</small><b>${esc(s.label)}</b><span>${esc(s.period)} · ${s.sampleSize?'n='+Number(s.sampleSize).toLocaleString('en-US'):'Sample size not publicly stated'} · published ${esc(s.publishedAt)}</span></div>${miButton('Survey methodology','survey-method',s.id)}</div><article class="ms-heat-card"><div class="ms-card-head"><div><span class="ux-eyebrow">${matrix.hasCategories?'PROVIDER × PAYMENT USE CASE':'PUBLISHED RESPONDENT PERCENTAGES'}</span><h4>${esc(s.metric)}</h4></div><span>% of defined respondents</span></div>${msLegend(true)}<div class="ms-heat-scroll"><table class="ms-share-table"><thead><tr><th>${matrix.hasBrands?'Wallet brand':'Wallet activity'}</th>${matrix.columns.map(c=>`<th>${esc(c.name)}<small>${esc(s.period)}</small></th>`).join('')}</tr></thead><tbody>${matrix.rows.map(row=>`<tr><th><div>${matrix.hasBrands?msLogo(row.id):''}<span>${esc(row.name)}</span></div></th>${matrix.columns.map(col=>{const o=matrix.observations.find(x=>(matrix.hasBrands?x.entityId:x.categoryId)===row.id&&(!matrix.hasCategories||x.categoryId===col.id));return `<td>${o?`<button class="ms-share-cell ms-share-${msShade(o.value)}" data-mi-action="survey-method" data-mi-key="${esc(s.id)}"><strong>${msPct(o.value)}</strong></button>`:'<span class="ms-missing">—</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="ms-chart-foot">${esc(s.definition)}</p></article><article class="mi-chart-card ms-share-chart"><div class="mi-chart-heading"><div><h4>${esc(matrix.hasCategories?matrix.columns[0].name:s.metric)}</h4><span>${esc(s.period)} · survey respondents</span></div></div><div class="mi-chart-area"><canvas id="msSurveyComparison" role="img" aria-label="Published survey respondent percentages"></canvas></div></article><div class="ms-source-strip">${miSource(s.sourceUrl,s.sourceName)}${miButton('Read sample and limitations','survey-method',s.id,'mi-detail-link')}</div><div class="ms-decision-note"><span class="ux-eyebrow">GOTO LENS · ANALYST INTERPRETATION</span><p>${esc(s.gotoImplication)}</p></div>`}
function msPaintSurvey(){const s=msSurveyCurrent();if(!s)return;const matrix=msSurveyMatrix(s),rows=matrix.observations.filter(o=>!matrix.hasCategories||o.categoryId===matrix.columns[0].id);miChart('msSurveyComparison','bar',rows.map(o=>o.company||o.category),[{label:'Survey respondents',data:rows.map(o=>o.value),backgroundColor:miColors,borderRadius:5,maxBarThickness:35}],{suffix:'%',options:{indexAxis:'y',scales:{x:{min:0,max:100}}}})}
function msOpenSurvey(id){const s=miData.surveys?.find(s=>s.id===id);if(!s)return;const labels={sampling:'Sampling',ageRange:'Age range',eligibility:'Eligibility',geographicCoverage:'Coverage',fieldwork:'Fieldwork',sampleSize:'Sample size',population:'Response population',parentSampleSize:'Parent study sample',sourceMethod:'Method'};gbOpenDialog(s.label,'SURVEY EVIDENCE · NOT TRANSACTION MARKET SHARE',`<div class="mi-metric-reader"><div class="ms-survey-boundary"><b>Respondent percentages, not transaction shares</b><span>${esc(s.definition)}</span></div><div class="mi-reader-measures"><article><small>FIELDWORK / REPORTING PERIOD</small><b>${esc(s.period)}</b></article><article><small>SAMPLE SIZE</small><b>${s.sampleSize?'n='+Number(s.sampleSize).toLocaleString('en-US'):'Not publicly stated'}</b></article></div>${s.methodology&&typeof s.methodology==='object'?'<h3>Study methodology</h3><dl class="ms-method-list">'+Object.entries(s.methodology).map(([k,v])=>'<div><dt>'+esc(labels[k]||k.replace(/([a-z])([A-Z])/g,'$1 $2'))+'</dt><dd>'+esc(v==null?'Not publicly stated':typeof v==='string'||typeof v==='number'?v:JSON.stringify(v))+'</dd></div>').join('')+'</dl>':''}<h3>Interpretation limits</h3><ul>${s.caveats.map(c=>'<li>'+esc(c)+'</li>').join('')}</ul><h3>Published observations</h3><div class="ux-table-wrap"><table class="ux-table"><thead><tr><th>Brand / activity</th><th>Question / use case</th><th>Respondents</th></tr></thead><tbody>${s.observations.map(o=>'<tr><td>'+esc(o.company||o.category)+'</td><td>'+esc(o.company?o.category||s.metric:s.metric)+'</td><td>'+msPct(o.value)+'</td></tr>').join('')}</tbody></table></div>${miSource(s.sourceUrl,s.sourceName)}</div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-mi-action]');if(!b)return;if(b.dataset.miAction==='survey-study'){miState.surveyMetric=b.dataset.miKey;miState.marketMode='surveys';miRender()}if(b.dataset.miAction==='survey-method')msOpenSurvey(b.dataset.miKey)});

